async function TAKE_CHECK() {
  return (await ITAKE_CHECK(g.P_PRSO, getb(g.P_SYNTAX, P_SLOC1))) && (await ITAKE_CHECK(g.P_PRSI, getb(g.P_SYNTAX, P_SLOC2)));
}

async function ITAKE_CHECK(tbl, ibits) {
  let ptr = 0, obj = 0, taken = 0;
  if ((ptr = get(tbl, g.P_MATCHLEN)) && (btst(ibits, SHAVE) || btst(ibits, STAKE))) {
    for (;;) {
      if ((ptr = ptr - 1) < 0) {
        return true;
      } else {
        obj = get(tbl, ptr + 1);
        if (obj == IT) {
          if (!(await ACCESSIBLE$(g.P_IT_OBJECT))) {
            tell("I don't see what you're referring to.\n");
            return false;
          } else {
            obj = g.P_IT_OBJECT;
          }
        }
        if (!(await HELD$(obj)) && !(obj == HANDS || obj == ME)) {
          g.PRSO = obj;
          if (hasFlag(obj, TRYTAKEBIT)) {
            taken = true;
          } else if (!(g.WINNER == ADVENTURER)) {
            taken = false;
          } else if (btst(ibits, STAKE) && eq(await ITAKE(false), true)) {
            taken = false;
          } else {
            taken = true;
          }
          if (taken && btst(ibits, SHAVE) && (g.WINNER == ADVENTURER)) {
            if (obj == NOT_HERE_OBJECT) {
              tell("You don't have that!\n");
              return false;
            }
            tell("You don't have the ");
            printD(obj);
            tell(".\n");
            return false;
          } else if (!taken && (g.WINNER == ADVENTURER)) {
            tell("(Taken)\n");
          }
        }
      }
    }
  } else {
    return true;
  }
}

async function MANY_CHECK() {
  let loss = false, tmp = 0;
  if ((get(g.P_PRSO, g.P_MATCHLEN) > 1) && !(btst(getb(g.P_SYNTAX, P_SLOC1), SMANY))) {
    loss = 1;
  } else if ((get(g.P_PRSI, g.P_MATCHLEN) > 1) && !(btst(getb(g.P_SYNTAX, P_SLOC2), SMANY))) {
    loss = 2;
  }
  if (loss) {
    tell("You can't use multiple ");
    if (loss == 2) {
      tell("in");
    }
    tell("direct objects with \"");
    tmp = get(g.P_ITBL, P_VERBN);
    if (tmp == 0) {
      tell("tell");
    } else if (g.P_OFLAG || g.P_MERGED) {
      printB(get(tmp, 0));
    } else {
      await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
    }
    tell("\".\n");
    return false;
  } else {
    return true;
  }
}

async function ZMEMQ(itm, tbl, size = (-1)) {
  let cnt = 1;
  if (!tbl) {
    return false;
  }
  if (!(size < 0)) {
    cnt = 0;
  } else {
    size = get(tbl, 0);
  }
  for (;;) {
    if (itm == get(tbl, cnt)) {
      return tbl + (cnt * 2);
    } else if (++cnt > size) {
      return false;
    }
  }
}

async function ZMEMQB(itm, tbl, size) {
  let cnt = 0;
  for (;;) {
    if (itm == getb(tbl, cnt)) {
      return true;
    } else if (++cnt > size) {
      return false;
    }
  }
}

async function LIT$(rm, rmbit = true) {
  let ohere = 0, lit = false;
  if (g.ALWAYS_LIT && (g.WINNER == g.PLAYER)) {
    return true;
  }
  g.P_GWIMBIT = ONBIT;
  ohere = g.HERE;
  g.HERE = rm;
  if (rmbit && hasFlag(rm, ONBIT)) {
    lit = true;
  } else {
    put(g.P_MERGE, g.P_MATCHLEN, 0);
    g.P_TABLE = g.P_MERGE;
    g.P_SLOCBITS = -1;
    if (ohere == rm) {
      await DO_SL(g.WINNER, 1, 1);
      if (!(g.WINNER == g.PLAYER) && (loc(g.PLAYER) == rm)) {
        await DO_SL(g.PLAYER, 1, 1);
      }
    }
    await DO_SL(rm, 1, 1);
    if (get(g.P_TABLE, g.P_MATCHLEN) > 0) {
      lit = true;
    }
  }
  g.HERE = ohere;
  g.P_GWIMBIT = 0;
  return lit;
}

async function THIS_IT$(obj, tbl) {
  let syns = 0;
  if (hasFlag(obj, INVISIBLE)) {
    return false;
  } else if (g.P_NAM && !(await ZMEMQ(g.P_NAM, syns = getPropAddr(obj, P.SYNONYM), div(propSize(syns), 2) - 1))) {
    return false;
  } else if (g.P_ADJ && (!(syns = getPropAddr(obj, P.ADJECTIVE)) || !(await ZMEMQB(g.P_ADJ, syns, propSize(syns) - 1)))) {
    return false;
  } else if (!(g.P_GWIMBIT == 0) && !(hasFlag(obj, g.P_GWIMBIT))) {
    return false;
  }
  return true;
}

async function ACCESSIBLE$(obj) {
  let l = loc(obj);
  if (hasFlag(obj, INVISIBLE)) {
    return false;
  } else if (!l) {
    return false;
  } else if (l == GLOBAL_OBJECTS) {
    return true;
  } else if ((l == LOCAL_GLOBALS) && (await GLOBAL_IN$(obj, g.HERE))) {
    return true;
  } else if (!(eq(await META_LOC(obj), g.HERE, loc(g.WINNER)))) {
    return false;
  } else if (l == g.WINNER || l == g.HERE || l == loc(g.WINNER)) {
    return true;
  } else if (hasFlag(l, OPENBIT) && (await ACCESSIBLE$(l))) {
    return true;
  } else {
    return false;
  }
}

async function META_LOC(obj) {
  for (;;) {
    if (!obj) {
      return false;
    } else if (loc(obj) == GLOBAL_OBJECTS) {
      return GLOBAL_OBJECTS;
    }
    if (loc(obj) == ROOMS) {
      return obj;
    } else {
      obj = loc(obj);
    }
  }
}

