async function V_DISENCHANT() {
  if (!(loc(g.PRSO) == g.HERE)) {
    return true;
  } else if ((g.SPELL_USED == W.FEEBLE || g.SPELL_USED == W.FUMBLE || g.SPELL_USED == W.FEAR) || (g.SPELL_USED == W.FREEZE || g.SPELL_USED == W.FALL || g.SPELL_USED == W.FERMENT) || (g.SPELL_USED == W.FIERCE || g.SPELL_USED == W.FENCE || g.SPELL_USED == W.FANTASIZE)) {
    if (hasFlag(g.PRSO, ACTORBIT)) {
      if (g.SPELL_USED == W.FEEBLE) {
        tell("The ", D(g.PRSO), " seems stronger now.\n");
        return true;
      } else if (g.SPELL_USED == W.FUMBLE) {
        tell("The ", D(g.PRSO), " no longer appears clumsy.\n");
        return true;
      } else if (g.SPELL_USED == W.FEAR) {
        tell("The ", D(g.PRSO), " no longer appears afraid.\n");
        return true;
      } else if (g.SPELL_USED == W.FREEZE) {
        tell("The ", D(g.PRSO), " moves again.\n");
        return true;
      } else if (g.SPELL_USED == W.FERMENT) {
        tell("The ", D(g.PRSO), " stops swaying.\n");
        return true;
      } else if (g.SPELL_USED == W.FIERCE) {
        tell("The ", D(g.PRSO), " appears more peaceful.\n");
        return true;
      } else {
        return false;
      }
    } else {
      return false;
    }
  } else if (g.SPELL_USED == W.FLOAT) {
    tell("The ", D(g.PRSO), " sinks to the ground.\n");
    return true;
  } else if (g.SPELL_USED == W.FUDGE) {
    tell("The sweet smell has dispersed.\n");
    return true;
  } else {
    return false;
  }
}

