async function V_EAT() {
  let eat$ = false, drink$ = false, nobj = false;
  if (eat$ = hasFlag(g.PRSO, FOODBIT)) {
    if (!(loc(g.PRSO) == g.WINNER) && !(loc(loc(g.PRSO)) == g.WINNER)) {
      tell("You're not holding that.\n");
    } else if (isVerb(V.DRINK)) {
      tell("How can you drink that?");
    } else {
      tell("Thank you very much. It really hit the spot.");
      await REMOVE_CAREFULLY(g.PRSO);
    }
    return crlf();
  } else if (hasFlag(g.PRSO, DRINKBIT)) {
    drink$ = true;
    nobj = loc(g.PRSO);
    if ((loc(g.PRSO) == GLOBAL_OBJECTS) || (await GLOBAL_IN$(GLOBAL_WATER, g.HERE)) || (g.PRSO == PSEUDO_OBJECT)) {
      return await HIT_SPOT();
    } else if (!nobj || !(await ACCESSIBLE$(nobj))) {
      tell("There isn't any water here.\n");
      return true;
    } else if ((await ACCESSIBLE$(nobj)) && !(loc(nobj) == g.WINNER)) {
      tell("You have to be holding the ", D(nobj), " first.\n");
      return true;
    } else if (!(hasFlag(nobj, OPENBIT))) {
      tell("You'll have to open the ", D(nobj), " first.\n");
      return true;
    } else {
      return await HIT_SPOT();
    }
  } else if (!(eat$ || drink$)) {
    tell("I don't think that the ", D(g.PRSO), " would agree with you.\n");
    return true;
  } else {
    return false;
  }
}

async function HIT_SPOT() {
  if ((g.PRSO == WATER) && !(await GLOBAL_IN$(GLOBAL_WATER, g.HERE))) {
    await REMOVE_CAREFULLY(g.PRSO);
  }
  tell("Thank you very much. I was rather thirsty (from all this talking, probably).\n");
  return true;
}

