async function V_ENCHANT() {
  if (g.WAND_ON) {
    g.SPELL_VICTIM = g.WAND_ON;
  }
  if (g.SPELL_VICTIM) {
    if (!g.SPELL_USED) {
      tell("You must be more specific.\n");
      return true;
    }
    if ((g.SPELL_USED == W.FEEBLE || g.SPELL_USED == W.FUMBLE || g.SPELL_USED == W.FEAR) || (g.SPELL_USED == W.FREEZE || g.SPELL_USED == W.FALL || g.SPELL_USED == W.FERMENT) || (g.SPELL_USED == W.FIERCE || g.SPELL_USED == W.FENCE || g.SPELL_USED == W.FANTASIZE)) {
      if (hasFlag(g.PRSO, ACTORBIT)) {
        tell("The wand stops glowing, but there is no other obvious effect.\n");
        return true;
      } else {
        tell("That might have done something, but it's hard to tell with a ", D(g.PRSO), ".\n");
        return true;
      }
    } else if (g.SPELL_USED == W.FUDGE) {
      tell("A strong odor of chocolate permeates the room.\n");
      return true;
    } else if (g.SPELL_USED == W.FLUORESCE) {
      setFlag(g.PRSO, LIGHTBIT);
      setFlag(g.PRSO, ONBIT);
      g.LIT = true;
      tell("The ", D(g.PRSO), " begins to glow.\n");
      return true;
    } else if (g.SPELL_USED == W.FILCH) {
      g.SPELL_HANDLED$ = true;
      if (hasFlag(g.PRSO, TAKEBIT)) {
        move(g.PRSO, g.WINNER);
        await SCORE_OBJ(g.PRSO);
        tell("Filched!\n");
        return true;
      } else {
        tell("You can't filch the ", D(g.PRSO), "!\n");
        return true;
      }
    } else if ((g.SPELL_USED == W.FLOAT) && hasFlag(g.PRSO, TAKEBIT)) {
      if ((g.SPELL_VICTIM == COLLAR) && (loc(COLLAR) == CERBERUS)) {
        g.SPELL_VICTIM = CERBERUS;
      }
      tell("The ", D(g.PRSO), " floats serenely in midair.\n");
      return true;
    } else if ((g.SPELL_USED == W.FRY) && hasFlag(g.PRSO, TAKEBIT)) {
      g.SPELL_HANDLED$ = true;
      await REMOVE_CAREFULLY(g.PRSO);
      tell("The ", D(g.PRSO), " goes up in a puff of smoke.\n");
      return true;
    } else {
      g.SPELL_VICTIM = false;
      tell("The wand stops glowing, but there is no other apparent effect.\n");
      return true;
    }
  } else {
    g.SPELL_VICTIM = false;
    tell("Nothing happens.\n");
    return true;
  }
}

async function REMOVE_CAREFULLY(obj) {
  let olit = 0;
  if (obj == g.P_IT_OBJECT) {
    g.P_IT_OBJECT = false;
  }
  olit = g.LIT;
  remove(obj);
  g.LIT = await LIT$(g.HERE);
  if (olit && !(olit == g.LIT)) {
    tell("You are left in the dark...\n");
  }
  return true;
}

