async function V_OPEN() {
  let f = 0, str = 0;
  if (hasFlag(g.PRSO, CONTBIT) && !(eq(getProp(g.PRSO, P.CAPACITY), 0))) {
    if (hasFlag(g.PRSO, OPENBIT)) {
      tell("It is already open.\n");
      return true;
    } else {
      setFlag(g.PRSO, OPENBIT);
      setFlag(g.PRSO, TOUCHBIT);
      if (!(first(g.PRSO)) || hasFlag(g.PRSO, TRANSBIT)) {
        tell("Opened.\n");
        return true;
      } else if ((f = first(g.PRSO)) && !(next(f)) && !(hasFlag(f, TOUCHBIT)) && (str = getProp(f, P.FDESC))) {
        tell("The ", D(g.PRSO), " opens.\n");
        tell(S(str), "\n");
        return true;
      } else {
        tell("Opening the ", D(g.PRSO), " reveals ");
        await PRINT_CONTENTS(g.PRSO);
        tell(".\n");
        return true;
      }
    }
  } else if (hasFlag(g.PRSO, DOORBIT)) {
    if (hasFlag(g.PRSO, OPENBIT)) {
      tell("It is already open.\n");
      return true;
    } else {
      tell("The ", D(g.PRSO), " opens.\n");
      return setFlag(g.PRSO, OPENBIT);
    }
  } else {
    tell("You must tell me how to do that to a ", D(g.PRSO), ".\n");
    return true;
  }
}

