async function V_PUT() {
  if (hasFlag(g.PRSI, OPENBIT) || (hasFlag(g.PRSI, DOORBIT) || hasFlag(g.PRSI, CONTBIT)) || hasFlag(g.PRSI, VEHBIT)) {
  } else {
    tell("You can't do that.\n");
    return true;
  }
  if (!(hasFlag(g.PRSI, OPENBIT))) {
    tell("The ", D(g.PRSI), " isn't open.\n");
    return await THIS_IS_IT(g.PRSI);
  } else if (g.PRSI == g.PRSO) {
    tell("How can you do that?\n");
    return true;
  } else if (loc(g.PRSO) == g.PRSI) {
    tell("The ", D(g.PRSO), " is already in the ", D(g.PRSI), ".\n");
    return true;
  } else if ((((await WEIGHT(g.PRSI)) + (await WEIGHT(g.PRSO))) - getProp(g.PRSI, P.SIZE)) > getProp(g.PRSI, P.CAPACITY)) {
    tell("There's no room.\n");
    return true;
  } else if (!(await HELD$(g.PRSO)) && hasFlag(g.PRSO, TRYTAKEBIT)) {
    tell("You don't have the ", D(g.PRSO), ".\n");
    return true;
  } else if (!(await HELD$(g.PRSO)) && !(await ITAKE())) {
    return true;
  } else {
    move(g.PRSO, g.PRSI);
    setFlag(g.PRSO, TOUCHBIT);
    await SCORE_OBJ(g.PRSO);
    tell("Done.\n");
    return true;
  }
}

