async function V_SHAKE() {
  if (hasFlag(g.PRSO, ACTORBIT)) {
    tell("This seems to have no effect.\n");
    return true;
  } else if (!(hasFlag(g.PRSO, TAKEBIT))) {
    tell("You can't take it; thus, you can't shake it!\n");
    return true;
  } else if (hasFlag(g.PRSO, CONTBIT)) {
    if (hasFlag(g.PRSO, OPENBIT)) {
      if (first(g.PRSO)) {
        await SHAKE_LOOP();
        tell("The contents of the ", D(g.PRSO), " spill ");
        if (!(hasFlag(g.HERE, RLANDBIT))) {
          tell("out and disappears");
        } else {
          tell("to the ground");
        }
        tell(".\n");
        return true;
      } else {
        tell("Shaken.\n");
        return true;
      }
    } else {
      if (first(g.PRSO)) {
        tell("It sounds like there is something inside the ", D(g.PRSO), ".\n");
        return true;
      } else {
        tell("The ", D(g.PRSO), " sounds empty.\n");
        return true;
      }
    }
  } else {
    tell("Shaken.\n");
    return true;
  }
}

async function SHAKE_LOOP() {
  let x = 0;
  for (;;) {
    if (x = first(g.PRSO)) {
      setFlag(x, TOUCHBIT);
      move(x, x == WATER ? PSEUDO_OBJECT : (!(hasFlag(g.HERE, RLANDBIT)) ? PSEUDO_OBJECT : g.HERE));
    } else {
      return true;
    }
  }
}

