async function I_FUSE() {
  let brick_room = loc(BRICK), f = 0;
  if (loc(FUSE) == BRICK) {
    loop1: for (;;) {
      if (!brick_room) {
        return false;
      } else if (loc(brick_room) == ROOMS) {
        break loop1;
      } else {
        brick_room = loc(brick_room);
      }
    }
    move(EXPLOSION, brick_room);
    clearFlag(brick_room, TOUCHBIT);
    if (brick_room == g.HERE) {
      (await MUNG_ROOM(brick_room, "The way is blocked by debris from an explosion."));
      await JIGS_UP(g.OTHER_PROPERTIES);
    } else if (brick_room == SAFE_ROOM) {
      enable(await QUEUE(I_SAFE.id, 5));
      g.MUNGED_ROOM = SAFE_ROOM;
      tell("There is an explosion nearby.\n");
      if (loc(BRICK) == SLOT) {
        setFlag(SLOT, INVISIBLE);
        setFlag(SAFE, OPENBIT);
        clearFlag(SAFE_ROOM, TOUCHBIT);
        g.SAFE_FLAG = true;
      }
    } else {
      tell("There is an explosion nearby.\n");
      enable(await QUEUE(I_SAFE.id, 5));
      g.MUNGED_ROOM = brick_room;
      if (f = first(brick_room)) {
        loop2: for (;;) {
          if (hasFlag(f, TAKEBIT)) {
            setFlag(f, INVISIBLE);
          }
          if (!(f = next(f))) {
            break loop2;
          }
        }
      }
    }
    remove(BRICK);
  } else if (eq(loc(FUSE), g.WINNER, g.HERE)) {
    tell("The string rapidly burns into nothingness.\n");
  }
  return remove(FUSE);
}

async function I_SAFE() {
  if (g.HERE == g.MUNGED_ROOM) {
    (await JIGS_UP("The room trembles and 5000 tons of rock fall on you, turning you into a pancake."));
  } else if (!g.DEAD) {
    tell("You may recall that recent explosion. Probably as a result of it, you hear an ominous rumbling, as if a nearby room had collapsed.\n");
    if (g.MUNGED_ROOM == SAFE_ROOM) {
      enable(await QUEUE(I_LEDGE.id, 8));
    }
  }
  return (await MUNG_ROOM(g.MUNGED_ROOM, "The way is blocked by debris from an explosion."));
}

async function I_LEDGE() {
  let rm = LEDGE_2;
  if (g.HERE == LEDGE_2) {
    if (loc(g.WINNER) == BALLOON) {
      if (g.BTIE_FLAG) {
        g.BLOC = VOLCANO_BOTTOM;
        remove(BALLOON);
        move(DEAD_BALLOON, VOLCANO_BOTTOM);
        g.BTIE_FLAG = false;
        g.BINF_FLAG = false;
        disable(await INT(I_BALLOON.id));
        disable(await INT(I_BURNUP.id));
        (await JIGS_UP("The ledge collapses, probably as a result of the explosion, and plummets to the ground far below. Sadly, you were still attached to the ledge."));
      } else {
        tell("The ledge collapses, leaving you with no place to land.\n");
      }
    } else {
      (await JIGS_UP("The force of the recent explosion has caused the ledge to collapse."));
    }
  } else if (!g.DEAD) {
    tell("The ledge collapses. (That was a narrow escape!)\n");
  }
  return (await MUNG_ROOM(rm, "The ledge has collapsed and cannot be landed on."));
}

