async function GNOME_FCN() {
  if (isVerb(V.TELL)) {
    g.P_CONT = false;
    g.QUOTE_FLAG = false;
    if (!g.GNOME_FLAG) {
      enable(await QUEUE(I_NERVOUS.id, 5));
    }
    g.GNOME_FLAG = true;
    tell("The gnome appears increasingly nervous.\n");
    return true;
  } else if (isVerb(V.GIVE, V.THROW) && (g.PRSI == GNOME)) {
    if (getPropAddr(g.PRSO, P.VALUE)) {
      tell("\"Thank you very much for the ", D(g.PRSO), ". I don't believe I've ever seen one as beautiful. Follow me,\" he says, and a door appears on the west end of the ledge. Through the door, you can see a narrow chimney sloping steeply downward. The gnome moves quickly, and disappears from sight.\n");
      remove(g.PRSO);
      remove(GNOME);
      return g.GNOME_DOOR_FLAG = true;
    } else if (await BOMB$(g.PRSO)) {
      move(BRICK, g.HERE);
      remove(GNOME);
      disable(await INT(I_GNOME.id));
      disable(await INT(I_NERVOUS.id));
      tell("\"That certainly wasn't what I had in mind,\" he says, and disappears.\n");
      return true;
    } else {
      await REMOVE_CAREFULLY(g.PRSO);
      tell("\"That wasn't quite what I had in mind,\" he says, crunching the ", D(g.PRSO), " in his rock-hard hands.\n");
      return true;
    }
  } else {
    tell("The gnome appears increasingly nervous.\n");
    if (!g.GNOME_FLAG) {
      enable(await QUEUE(I_NERVOUS.id, 5));
    }
    return g.GNOME_FLAG = true;
  }
}

