async function FIXED_FONT_ON() {
  return put(0, 8, get(0, 8) | 2);
}

async function FIXED_FONT_OFF() {
  return put(0, 8, get(0, 8) & (-3));
}

async function POOL_FCN() {
  if (isVerb(V.DRINK)) {
    tell("The water is extremely salty.\n");
    return true;
  } else if (isVerb(V.LOOK_UNDER)) {
    tell("You'd probably have to enter the pool to see what's below the surface.\n");
    return true;
  } else if (isVerb(V.THROUGH)) {
    return (await JIGS_UP("You enter the pool, thrash around for a good while, and then drown. Sad, but true."));
  } else {
    return false;
  }
}

async function FLASK_FCN() {
  if (isVerb(V.LOOK_INSIDE)) {
    tell("You notice that objects behind the flask appear to be magnified. You might try looking at something through the flask.\n");
    return true;
  } else if (isVerb(V.READ) && (g.PRSI == FLASK)) {
    tell("The flask distorts and magnifies the ", D(g.PRSO), ", showing details not noticed earlier.\n");
    return false;
  } else if (isVerb(V.OPEN)) {
    (await MUNG_ROOM(g.HERE, "Noxious vapors prevent your entry."));
    return await JIGS_UP(g.FATAL_VAPORS);
  } else if (isVerb(V.MUNG, V.THROW)) {
    tell("The flask breaks into pieces.\n");
    remove(g.PRSO);
    return await JIGS_UP(g.FATAL_VAPORS);
  } else {
    return false;
  }
}

async function PLEAK() {
  let $1;
  if (isVerb(V.TAKE)) {
    $1 = await PICK_ONE(g.YUKS);
    tell(S($1));
    tell("\n");
    return true;
  } else if (isVerb(V.PLUG)) {
    tell("The leak is too high above you to reach.\n");
    return true;
  } else {
    return false;
  }
}

async function ICEBOOM() {
  (await MUNG_ROOM(g.HERE, "The entrance is blocked by sticky orange rubble. Probably some careless adventurer was playing with blasting cakes."));
  return (await JIGS_UP("You have been blasted to smithereens (wherever they are)."));
}

async function MAGNET_ROOM_FCN(rarg) {
  if (rarg == M_LOOK) {
    tell("You are in a circular room with a low ceiling. There are exits to the east and southeast.\n");
    return true;
  } else if ((rarg == M_ENTER) && g.CAROUSEL_FLIP_FLAG) {
    if (g.CAROUSEL_ZOOM_FLAG) {
      return (await JIGS_UP((ADVENTURER == g.WINNER ? "According to Prof. TAA of GUE Tech, the rapidly changing magnetic fields in the room are intense enough to electrocute you. I really don't know, but in any event, something just killed you." : "According to Prof. TAA of GUE Tech, the magnetic fields in the room are intense enough to fry the delicate innards of the robot. I really don't know, but in any event, smoke pours from its ears and it has stopped moving.")));
    } else if (g.WINNER == ADVENTURER) {
      tell("As you enter, your compass starts spinning wildly.\n");
      if (!g.COMPASS_KLUDGE) {
        tell("What compass, you ask? The one which allows you to specify compass directions for movement.");
        g.COMPASS_KLUDGE = true;
      }
      return crlf();
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function MAGNET_ROOM_EXIT() {
  if (g.CAROUSEL_FLIP_FLAG && (g.WINNER == ADVENTURER)) {
    tell("You cannot get your bearings...\n\n");
    if (50 > random(100)) {
      return MACHINE_ROOM;
    } else {
      return TEA_ROOM;
    }
  } else if (g.PRSO == P.EAST) {
    return MACHINE_ROOM;
  } else if ((g.PRSO == P.SE) || (g.PRSO == P.OUT)) {
    return TEA_ROOM;
  } else {
    tell("You can't go that way.\n");
    return false;
  }
}

async function BUTTONS() {
  if (isVerb(V.PUSH)) {
    if (g.WINNER == ADVENTURER) {
      return (await JIGS_UP("There is a giant spark and you are fried to a crisp."));
    } else if (g.PRSO == SQUARE_BUTTON) {
      if (g.CAROUSEL_ZOOM_FLAG) {
        tell("Nothing seems to happen.\n");
        return true;
      } else {
        g.CAROUSEL_ZOOM_FLAG = true;
        tell("The whirring increases in intensity.\n");
        return true;
      }
    } else if (g.PRSO == ROUND_BUTTON) {
      if (g.CAROUSEL_ZOOM_FLAG) {
        g.CAROUSEL_ZOOM_FLAG = false;
        tell("The whirring decreases in intensity.\n");
        return true;
      } else {
        tell("Nothing seems to happen.\n");
        return true;
      }
    } else if (g.PRSO == TRIANGULAR_BUTTON) {
      g.CAROUSEL_FLIP_FLAG = !g.CAROUSEL_FLIP_FLAG;
      if (loc(IRON_BOX) == CAROUSEL_ROOM) {
        tell("A dull thump is heard in the distance.\n");
        if (hasFlag(IRON_BOX, INVISIBLE)) {
          clearFlag(IRON_BOX, INVISIBLE);
        } else {
          setFlag(IRON_BOX, INVISIBLE);
        }
        if (!(hasFlag(IRON_BOX, INVISIBLE))) {
          clearFlag(CAROUSEL_ROOM, TOUCHBIT);
        }
        return true;
      } else {
        tell("Click.\n");
        return true;
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function SPHERE_FCN() {
  let fl = 0;
  if (!g.CAGE_SOLVE_FLAG && isVerb(V.TAKE, V.MOVE, V.PUT)) {
    fl = true;
  } else {
    fl = false;
  }
  if (fl && (ADVENTURER == g.WINNER)) {
    tell("As you reach for the sphere, a solid steel cage falls from the ceiling to entrap you. To make matters worse, poisonous gas starts coming into the room.\n\n");
    if (loc(ROBOT) == g.HERE) {
      move(ROBOT, IN_CAGE);
      setFlag(ROBOT, NDESCBIT);
    }
    await GOTO(IN_CAGE);
    move(CAGE, g.HERE);
    setFlag(CAGE, NDESCBIT);
    clearFlag(CAGE, INVISIBLE);
    enable(await QUEUE(I_SPHERE.id, 6));
    return true;
  } else if (fl) {
    setFlag(PALANTIR_1, INVISIBLE);
    remove(ROBOT);
    setFlag(g.PRSO, INVISIBLE);
    move(CAGE, CAGE_ROOM);
    clearFlag(CAGE, INVISIBLE);
    (await JIGS_UP("As the robot reaches for the sphere, a solid steel cage falls from the ceiling, trapping him. You can faintly hear his last words: \"Whirr, buzz, click!\" A cloud of smoke rising from beneath the cage confirms your fears about the fate of your brave mechanical friend."));
    return true;
  } else if (isVerb(V.LOOK_INSIDE, V.EXAMINE)) {
    return await PALANTIR();
  } else {
    return false;
  }
}

async function I_SPHERE() {
  if (g.HERE == CAGE_ROOM || g.HERE == IN_CAGE) {
    setFlag(PALANTIR_1, INVISIBLE);
    (await MUNG_ROOM(CAGE_ROOM, "You are stopped by a cloud of poisonous gas."));
    return (await JIGS_UP("Time passes...and you die from some obscure poisoning."));
  } else {
    return false;
  }
}

async function IN_CAGE_FCN(rarg) {
  if (g.CAGE_SOLVE_FLAG) {
    return g.HERE = CAGE_ROOM;
  } else {
    return false;
  }
}

async function ROBOT_FCN(rarg = M_OBJECT) {
  if (g.WINNER == ROBOT) {
    if (isVerb(V.SGIVE)) {
      return false;
    } else if (isVerb(V.FOLLOW)) {
      tell("\"My memory circuits are not that advanced. I can move as directed, though.\"\n");
      return true;
    } else if (isVerb(V.RAISE, V.TAKE, V.MOVE) && (g.PRSO == CAGE)) {
      tell("The cage shakes and is hurled across the room. It's hard to say, but the robot appears to be smiling.\n\n");
      disable(await INT(I_SPHERE.id));
      g.WINNER = ADVENTURER;
      await GOTO(CAGE_ROOM);
      move(MANGLED_CAGE, CAGE_ROOM);
      clearFlag(ROBOT, NDESCBIT);
      setFlag(PALANTIR_1, TAKEBIT);
      move(ROBOT, CAGE_ROOM);
      return g.CAGE_SOLVE_FLAG = true;
    } else if (isVerb(V.EAT, V.DRINK)) {
      if (loc(ADVENTURER) == g.HERE) {
        tell("\"I am sorry but that is difficult for a being with no mouth.\"\n");
      }
      return true;
    } else if ((2 > random(100)) && eq(await META_LOC(ADVENTURER), g.HERE)) {
      tell("\"Buzz! Buzz! Buzz! My circuits are getting rusty. Try again.\"\n");
      return true;
    } else if (isVerb(V.READ, V.EXAMINE)) {
      if (eq(await META_LOC(ADVENTURER), g.HERE)) {
        tell("\"My vision is not sufficiently acute to do that.\"\n");
      }
      return true;
    } else if (isVerb(V.DROP, V.PUT, V.THROW)) {
      if (!(eq(await META_LOC(ADVENTURER), g.HERE))) {
        return false;
      } else if (loc(g.PRSO) == ROBOT) {
        tell("\"Whirr, buzz, click!\"\n");
        return false;
      } else {
        tell("\"Click! I don't have that. Buzz! Whirr!\"\n");
        return true;
      }
    } else if (isVerb(V.WALK) || (isVerb(V.TAKE, V.PUSH, V.TURN) && !(hasFlag(g.PRSO, ACTORBIT)))) {
      if (!(eq(await META_LOC(ADVENTURER), g.HERE))) {
        return false;
      } else if (80 > random(100)) {
        tell("\"Whirr, buzz, click!\"\n");
      } else {
        tell("\"Buzz, click, whirr!\"\n");
      }
      return false;
    } else {
      if (eq(await META_LOC(ADVENTURER), g.HERE)) {
        tell("\"My programming is insufficient to allow me to perform that task.\"\n");
      }
      return true;
    }
  } else if (isVerb(V.OPEN, V.LOOK_INSIDE, V.CLOSE)) {
    tell("There's no access panel or door on the robot.\n");
    return true;
  } else if (isVerb(V.GIVE) && (g.PRSI == ROBOT)) {
    move(g.PRSO, ROBOT);
    tell("The robot gladly takes the ", D(g.PRSO), " and nods his head-like appendage in thanks.\n");
    return true;
  } else if (isVerb(V.THROW, V.MUNG)) {
    tell("The robot falls to the ground and (being of shoddy construction) disintegrates before your eyes.\n");
    return remove(isVerb(V.THROW) ? g.PRSI : (g.PRSO || false));
  } else {
    return false;
  }
}

async function BILLS_OBJECT() {
  g.BANK_SOLVE_FLAG = true;
  if (isVerb(V.BURN)) {
    tell("Nothing like having money to burn!\n");
    return false;
  } else if (isVerb(V.EAT)) {
    tell("Talk about eating rich foods!\n");
    return true;
  } else {
    return false;
  }
}

async function BKLEAVEE(rm = TELLER_EAST) {
  if ((await HELD$(BILLS)) || (await HELD$(PORTRAIT))) {
    tell("An alarm rings briefly, and an invisible force bars your way.\n");
    return false;
  } else {
    return rm;
  }
}

async function BKLEAVEW() {
  return await BKLEAVEE(TELLER_WEST);
}

async function DEPOSITORY_FCN(rarg) {
  if (rarg == M_ENTER) {
    return g.SCOL_ROOM = await LKP(g.PRSO, g.SCOL_ROOMS);
  } else {
    return false;
  }
}

async function TELLER_ROOM(rarg) {
  if (rarg == M_LOOK) {
    tell("You are in a small room, which was used by a bank officer who retrieved safety deposit boxes for the customer. On the north side of the room is a sign which reads  \"Viewing Room\". On the ");
    if (g.HERE == TELLER_WEST) {
      tell("west");
    } else {
      tell("east");
    }
    tell(" side of the room, above an open door, is a sign reading:\n\n          BANK PERSONNEL ONLY\n\n");
    return true;
  } else {
    return false;
  }
}

async function SCOL_OBJECT(obj = false) {
  if (isVerb(V.PUSH, V.MOVE, V.TAKE, V.RUB)) {
    tell("As you try, your hand seems to go through it.\n");
    return true;
  } else if (isVerb(V.ATTACK) && g.PRSI) {
    tell("The ", D(g.PRSI), " goes through it.\n");
    return true;
  } else if (isVerb(V.THROW, V.OVERBOARD) && (g.PRSI == CURTAIN || g.PRSI == obj)) {
    if (loc(g.PRSO) == g.WINNER) {
      return await V_THROUGH(g.PRSO);
    } else {
      tell("You don't have that!\n");
      return true;
    }
  } else {
    return false;
  }
}

async function GET_WALL(rm) {
  let w_ = 0;
  w_ = g.SCOL_WALLS;
  for (;;) {
    if (eq(get(w_, 0), rm)) {
      return w_;
    } else {
      w_ = w_ + 6;
    }
  }
}

async function SCOLWALL() {
  if (isVerb(V.THROW, V.OVERBOARD, V.PUT) && (g.HERE == g.SCOL_ACTIVE) && (g.PRSI == get(await GET_WALL(g.HERE), 1))) {
    return await SCOL_OBJECT(g.PRSI);
  } else {
    return false;
  }
}

async function SCOL_GO(obj) {
  g.SCOL_ACTIVE = g.SCOL_ROOM;
  if (obj) {
    return await SCOL_OBJ(obj, 0, g.SCOL_ROOM);
  } else {
    return await SCOL_THROUGH(12, g.SCOL_ROOM);
  }
}

async function SCOL_OBJ(obj, cint, rm) {
  enable(await QUEUE(I_CURTAIN.id, cint));
  move(obj, rm);
  if (rm == DEPOSITORY) {
    tell("The ", D(obj), " passes through the wall and vanishes.\n");
    return true;
  } else {
    tell("The curtain dims slightly as the ", D(obj), " passes through.\n");
    g.SCOL_ROOM = false;
    return true;
  }
}

async function SCOL_THROUGH(cint, rm) {
  enable(await QUEUE(I_CURTAIN.id, cint));
  tell("You feel somewhat disoriented as you pass through...\n\n");
  return await GOTO(rm);
}

async function I_CURTAIN() {
  g.SCOL_ACTIVE = false;
  if (g.HERE == VAULT) {
    return (await JIGS_UP("A metallic voice says \"Hello, Intruder! Your unauthorized presence in the vault of the Bank of Zork has set off all sorts of nasty surprises, most of which are fatal. This message brought to you by the Frobozz Magic Vault Company.\""));
  } else if (g.HERE == VIEWING_EAST || g.HERE == VIEWING_WEST || g.HERE == SMALL_ROOM) {
    tell("You hear a faint voice say \"Curtain Door Closed.\"\n");
    if (g.HERE == SMALL_ROOM) {
      if (g.ZGNOME_FLAG) {
        return true;
      } else {
        enable(await QUEUE(I_ZGNOME.id, 3));
        return g.ZGNOME_FLAG = true;
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function I_ZGNOME() {
  if (g.HERE == SMALL_ROOM) {
    enable(await QUEUE(I_ZGNOME_OUT.id, 12));
    tell("An epicene gnome of Zurich wearing a three-piece suit and carrying a safety deposit box materializes in the room.");
    if (loc(WAND) == g.WINNER) {
      tell(" He notices the wand and dematerializes speedily.\n");
      return true;
    } else {
      tell(" \"You seem to have forgotten to deposit your valuables,\" he says, tapping the lid of the box impatiently. \"We don't usually allow customers to use the boxes here, but we can make this ONE exception, I suppose...\" He looks askance at you over his wire-rimmed bifocals.\n");
      return move(GNOME_OF_ZURICH, g.HERE);
    }
  } else {
    return false;
  }
}

async function BOX_F() {
  tell("The gnome clutches it possessively.\n");
  return true;
}

async function ZGNOME_FCN() {
  if (isVerb(V.TELL)) {
    g.P_CONT = false;
    g.QUOTE_FLAG = false;
    tell("The gnome appears increasingly impatient.\n");
    return true;
  } else if (isVerb(V.GIVE, V.THROW) && (g.PRSI == GNOME_OF_ZURICH)) {
    if (getPropAddr(g.PRSO, P.VALUE)) {
      tell("The gnome carefully places the ", D(g.PRSO), " in the deposit box. \"Let me show you the way out,\" he says, making it clear he will be pleased to see the last of you. Then, you are momentarily disoriented, and when you recover you are back at the Bank Entrance.\n");
      remove(GNOME_OF_ZURICH);
      remove(g.PRSO);
      disable(await INT(I_ZGNOME_OUT.id));
      await GOTO(BANK_ENTRANCE);
      return true;
    } else if (await BOMB$(g.PRSO)) {
      remove(GNOME_OF_ZURICH);
      move(g.PRSO, g.HERE);
      disable(await INT(I_ZGNOME.id));
      disable(await INT(I_ZGNOME_OUT.id));
      tell("\"You are so very gracious. I really cannot accept.\" he says. He disappears, a wry smile on his lips.\n");
      return true;
    } else {
      tell("\"I wouldn't put THAT in a safety deposit box,\" remarks the gnome with disdain, tossing it over his shoulder, where it disappears with an understated \"pop\".\n");
      await REMOVE_CAREFULLY(g.PRSO);
      return true;
    }
  } else if (isVerb(V.ATTACK)) {
    tell("The gnome says \"Well, I never...\" and disappears with a snap of his fingers, leaving you alone.\n");
    remove(GNOME_OF_ZURICH);
    return disable(await INT(I_ZGNOME_OUT.id));
  } else {
    tell("The gnome appears increasingly impatient.\n");
    return true;
  }
}

async function I_ZGNOME_OUT() {
  remove(GNOME_OF_ZURICH);
  if (g.HERE == SMALL_ROOM) {
    tell("The gnome looks impatient: \"I may have another customer waiting; you'll just have to fend for yourself, I'm afraid.\" He disappears, leaving you alone.\n");
    return true;
  } else {
    return false;
  }
}

async function BOMB$(o) {
  if ((o == BRICK) && (loc(FUSE) == BRICK) && !(get(await INT(I_FUSE.id), C_ENABLED$) == 0)) {
    return true;
  } else {
    return false;
  }
}

async function GO_LOOK(rm) {
  let ohere = 0, olit = 0, oseen = false;
  ohere = g.HERE;
  if (hasFlag(ohere, TOUCHBIT)) {
    oseen = true;
  }
  olit = g.LIT;
  g.HERE = rm;
  g.LIT = await LIT$(rm);
  await PERFORM(V.LOOK);
  if (!oseen) {
    clearFlag(ohere, TOUCHBIT);
  }
  g.HERE = ohere;
  g.LIT = olit;
  return true;
}

async function TINY_ROOM_FCN(rarg) {
  if (rarg == M_LOOK) {
    tell("This is a tiny room carved out of the wall of the ravine. There is an exit down a precarious climb. ");
    (await P_DOOR("north", LID_1, KEYHOLE_1));
    return true;
  } else if (!(isVerb(V.LOOK))) {
    await PCHECK();
    return false;
  } else {
    return false;
  }
}

async function DREARY_ROOM_FCN(rarg) {
  if (rarg == M_LOOK) {
    tell("This is a small and rather dreary room, eerily illuminated by a red glow emanating from a crack in one wall. The light falls upon a dusty wooden table in the center of the room. ");
    (await P_DOOR("south", LID_2, KEYHOLE_2));
    return true;
  }
  await PCHECK();
  return false;
}

async function PCHECK() {
  let lid = (await PLID());
  g.PLOOK_FLAG = false;
  if ((loc(KEY) == KEYHOLE_1) || (loc(KEY) == KEYHOLE_2)) {
    setFlag(KEY, NDESCBIT);
  } else {
    clearFlag(KEY, NDESCBIT);
  }
  if (await HELD$(PLACE_MAT)) {
    g.MUD_FLAG = false;
  }
  if (g.MUD_FLAG) {
    move(PLACE_MAT, g.HERE);
    return setFlag(PLACE_MAT, NDESCBIT);
  } else {
    return clearFlag(PLACE_MAT, NDESCBIT);
  }
}

async function P_DOOR(str, lid, keyhole) {
  let f = 0;
  if (g.PLOOK_FLAG) {
    g.PLOOK_FLAG = false;
    return false;
  }
  tell("On the ", S(str), " side of the room is a massive wooden door, which has a small window barred with iron. A formidable bolt lock is set within the door frame. A keyhole ");
  if (!(hasFlag(lid, OPENBIT))) {
    tell("covered by a thin metal lid ");
  }
  tell("lies within the lock.");
  if (f = first(keyhole)) {
    tell(" A ", D(f), " is in place within the keyhole.");
  }
  if (g.MUD_FLAG) {
    tell(" The edge of a place mat is visible under the door.");
    if (g.MATOBJ) {
      tell(" Lying on the place mat is a ", D(g.MATOBJ), ".");
    }
  }
  return crlf();
}

async function PLID(obj1 = LID_1, obj2 = LID_2) {
  if (loc(obj1) == g.HERE) {
    return obj1;
  } else {
    return obj2;
  }
}

async function PKH(keyhole, this_ = false) {
  if ((keyhole == KEYHOLE_1) && !this_) {
    return KEYHOLE_2;
  } else if (!(keyhole == KEYHOLE_1) && this_) {
    return KEYHOLE_2;
  } else {
    return KEYHOLE_1;
  }
}

async function PKH_FCN() {
  let obj = 0, kh = 0;
  if (isVerb(V.LOOK_INSIDE)) {
    if (hasFlag(LID_1, OPENBIT) && hasFlag(LID_2, OPENBIT) && !(first(KEYHOLE_1)) && !(first(KEYHOLE_2)) && (await LIT$(g.HERE == DREARY_ROOM ? TINY_ROOM : DREARY_ROOM))) {
      tell("You can see a lighted room at the other end.\n");
      return true;
    } else {
      tell("No light can be seen through the keyhole.\n");
      return true;
    }
  } else if (isVerb(V.PUT)) {
    if (hasFlag(await PLID(), OPENBIT)) {
      if (first(await PKH(g.PRSI, true))) {
        tell("The keyhole is blocked.\n");
        return true;
      } else if (g.PRSO == LETTER_OPENER || g.PRSO == KEY) {
        if (first(kh = await PKH(g.PRSI))) {
          tell("There is a faint noise from behind the door and a small cloud of dust rises from beneath it.\n");
          obj = first(kh);
          remove(obj);
          if (g.MUD_FLAG) {
            g.MATOBJ = obj;
          }
          return false;
        } else {
          return false;
        }
      } else {
        tell("The ", D(g.PRSO), " doesn't fit.\n");
        return true;
      }
    } else {
      tell("The lid is in the way.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function PLID_FCN() {
  let $1;
  if (isVerb(V.OPEN, V.RAISE, V.MOVE)) {
    if (hasFlag(g.PRSO, OPENBIT)) {
      $1 = await RANDOM_ELEMENT(g.DUMMY);
      tell(S($1));
      tell("\n");
    } else {
      tell("The lid is now open.\n");
    }
    return setFlag(g.PRSO, OPENBIT);
  } else if (isVerb(V.CLOSE, V.LOWER)) {
    if (first(g.HERE == DREARY_ROOM ? KEYHOLE_2 : KEYHOLE_1)) {
      tell("The keyhole is occupied.\n");
      return true;
    } else {
      tell("The lid covers the keyhole.\n");
      return clearFlag(g.PRSO, OPENBIT);
    }
  } else if (isVerb(V.LOOK_BEHIND)) {
    tell("There's a keyhole behind the lid.\n");
    return true;
  } else {
    return false;
  }
}

async function ROOM$(obj) {
  let nobj = 0;
  for (;;) {
    nobj = loc(obj);
    if (!nobj) {
      return false;
    } else if (nobj == g.WINNER) {
      return false;
    } else if (nobj == ROOMS) {
      return obj;
    }
    obj = nobj;
  }
}

async function PALANTIR() {
  if (isVerb(V.LOOK_INSIDE)) {
    return await PALANTIR_LOOK(g.PRSO == PALANTIR_1 ? PALANTIR_2 : (g.PRSO == PALANTIR_2 ? PALANTIR_3 : (g.PRSO == PALANTIR_3 ? PALANTIR_1 : PALANTIR_4)));
  } else if (isVerb(V.EXAMINE)) {
    tell("There is something misty in the sphere. Perhaps if you were to look into it...\n");
    return true;
  } else if (isVerb(V.TAKE) && (g.PRSO == PALANTIR_3)) {
    putProp(g.PRSO, P.LDESC, false);
    return false;
  } else {
    return false;
  }
}

async function DEAD_PALANTIR(rarg) {
  let p_ = 0;
  if (rarg == M_LOOK) {
    tell("You are inside a huge crystalline sphere filled with thin ", S((g.HERE == DEAD_PALANTIR_1 ? (p_ = PALANTIR_1, "red") : (g.HERE == DEAD_PALANTIR_2 ? (p_ = PALANTIR_2, "blue") : (p_ = PALANTIR_3, "white")))), " mist. The mist becomes ", S((g.HERE == DEAD_PALANTIR_1 ? "blue" : (g.HERE == DEAD_PALANTIR_2 ? "white" : "black"))), " to the west.\n");
    tell("You strain to look out through the mist... \n");
    if (hasFlag(p_, TOUCHBIT)) {
      await PALANTIR_LOOK(p_, true);
    } else if (p_ == PALANTIR_1) {
      tell("You see a small room with a sign on the wall, but it is too blurry to read.\n");
    } else if (p_ == PALANTIR_2) {
      tell("You look out into a large, dreary room with a great door and a huge table. There is an odd glow to the mist.\n");
    } else if (p_ == PALANTIR_3) {
      tell("A strange blurry room is barely visible.");
      if ((loc(SERPENT) == AQUARIUM) && (25 > random(100))) {
        tell(" An odd sinuous shadow crosses the mist as you look.");
      }
      crlf();
    }
    return true;
  } else if ((rarg == M_ENTER) && (g.HERE == DEAD_PALANTIR_4)) {
    tell("You follow a corridor of black mist into a black walled spherical room.");
    if (loc(GENIE) == PENTAGRAM_ROOM) {
      tell(" The room is empty. A huge face looks down on you from outside and laughs sardonically. It doesn't look like you're getting out of this predicament!\n");
      await FINISH();
    }
    tell(" As you enter, a huge and horrible face materializes out of the mist.\n\n\"What brings you here to trouble my imprisonment, wanderer?\" it asks. Hearing no immediate answer, it studies you for a moment.\n");
    if (!(g.DEATHS < 3)) {
      tell("\"Not you again! This is getting tedious. You'll obviously never be much help to me. Better luck next time, oh wondrous adventurer.\" The face disappears and everything goes black.\n");
      return await FINISH();
    } else {
      tell("\"Perhaps you may be of some use to me in gaining my freedom from this place. Return to your foolish quest! I shall not destroy you this time. Mayhap you will repay this favor in kind someday.\" The face vanishes and the mist begins to swirl. When it clears you are returned to the world of life.\n");
      g.DEAD = false;
      await GOTO(INSIDE_BARROW);
      return true;
    }
  } else {
    return false;
  }
}

async function GLOBAL_PALANTIRS() {
  if (isVerb(V.LOOK_INSIDE, V.EXAMINE)) {
    return await DEAD_PALANTIR(M_LOOK);
  } else if (isVerb(V.MUNG)) {
    tell("The sphere is unbreakable.\n");
    return true;
  } else {
    return false;
  }
}

async function PALANTIR_LOOK(obj, inside$ = false) {
  let rm = 0, ohere = 0;
  if (obj == PALANTIR_4) {
    tell("As you peer into the sphere, a strange vision takes shape...a huge and fearful face with yellow eyes. The face peers out at you expectantly.\n");
    return true;
  }
  rm = await ROOM$(obj);
  if (!rm || !(await LIT$(rm))) {
    tell("You see only darkness.\n");
  } else if ((loc(obj) == rm) || (await SEE_INSIDE$(loc(obj)))) {
    ohere = g.HERE;
    if (inside$) {
      tell("As you peer through the mist, a strangely colored vision of a huge room takes shape...\n\n");
    } else {
      tell("As you peer into the sphere, a strange vision takes shape of a distant room, which can be described clearly....\n\n");
    }
    setFlag(obj, INVISIBLE);
    await GO_LOOK(rm);
    if (ohere == rm) {
      tell("An astonished adventurer is staring into a crystal sphere.\n");
    }
    clearFlag(obj, INVISIBLE);
    if (!inside$) {
      tell("The vision fades, revealing only an ordinary crystal sphere.\n");
    }
  } else {
    tell("You see only darkness.\n");
  }
  return true;
}

async function PWINDOW_FCN() {
  if (isVerb(V.LOOK_INSIDE)) {
    g.PLOOK_FLAG = true;
    if (hasFlag(PDOOR, OPENBIT)) {
      tell("The door is open, dummy.\n");
      return true;
    } else if (g.HERE == DREARY_ROOM) {
      return await GO_LOOK(TINY_ROOM);
    } else {
      return await GO_LOOK(DREARY_ROOM);
    }
  } else if (isVerb(V.THROUGH)) {
    tell("Perhaps if you were diced....\n");
    return true;
  } else {
    return false;
  }
}

async function PDOOR_FCN() {
  let k = 0;
  if (isVerb(V.LOOK_UNDER) && g.MUD_FLAG) {
    tell("The place mat is under the door.\n");
    return true;
  } else if (isVerb(V.UNLOCK)) {
    if (g.PRSI == KEY) {
      if ((k = first(await PLID(KEYHOLE_1, KEYHOLE_2))) && !(k == KEY)) {
        tell("The keyhole is blocked.\n");
        return true;
      } else {
        tell("The door is now unlocked.\n");
        return g.PUNLOCK_FLAG = true;
      }
    } else if (g.PRSI == GOLD_KEY) {
      tell("It doesn't fit the lock.\n");
      return true;
    } else {
      tell("It can't be unlocked with that.\n");
      return true;
    }
  } else if (isVerb(V.LOCK)) {
    if (g.PRSI == KEY) {
      tell("The door is locked.\n");
      g.PUNLOCK_FLAG = false;
      return true;
    } else if (g.PRSI == GOLD_KEY) {
      tell("It doesn't fit the lock.\n");
      return true;
    } else {
      tell("It can't be locked with that.\n");
      return true;
    }
  } else if (isVerb(V.PUT_UNDER)) {
    if (g.PRSO == ROBOT_LABEL) {
      tell("The paper is very small and vanishes under the door.\n");
      return move(g.PRSO, g.HERE == TINY_ROOM ? DREARY_ROOM : TINY_ROOM);
    } else if (g.PRSO == NEWSPAPER) {
      tell("The newspaper crumples up and won't go under the door.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.OPEN, V.CLOSE)) {
    if (g.PUNLOCK_FLAG) {
      return (await OPEN_CLOSE(g.PRSO, "The door is now open.", "The door is now closed."));
    } else {
      tell("The door is locked.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function PKEY_FCN() {
  if (isVerb(V.TURN)) {
    if (g.PUNLOCK_FLAG) {
      return await PERFORM(V.LOCK, PDOOR, g.PRSO);
    } else {
      return await PERFORM(V.UNLOCK, PDOOR, g.PRSO);
    }
  } else {
    return false;
  }
}

async function PLACE_MAT_FCN() {
  if (isVerb(V.PUT_UNDER)) {
    if (g.PRSI == PDOOR) {
      tell("The place mat fits easily under the door.\n");
      move(g.PRSO, g.HERE);
      return g.MUD_FLAG = true;
    } else if (g.PRSI == WIZ_DOOR || g.PRSI == RIDDLE_DOOR || g.PRSI == CRYPT_DOOR) {
      tell("There's not enough room under this door.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.TAKE, V.MOVE) && g.MATOBJ) {
    move(g.MATOBJ, g.HERE);
    tell("As the place mat is moved, a ", D(g.MATOBJ), " falls from it and onto the floor.\n");
    g.MATOBJ = false;
    g.MUD_FLAG = false;
    return true;
  } else {
    return false;
  }
}

async function WISH_FCN() {
  if (isVerb(V.MAKE)) {
    if ((g.HERE == WELL_BOTTOM) && (loc(COIN) == g.HERE)) {
      tell("A whispering voice replies: \"Water makes the bucket go.\" Unfortunately, wishing makes the coin go....\n");
      return remove(COIN);
    } else {
      tell("No one is listening.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function WELL_FCN() {
  if (hasFlag(g.PRSO, TAKEBIT) && isVerb(V.THROW, V.PUT, V.DROP)) {
    tell("The ", D(g.PRSO), " is now sitting at the bottom of the well.\n");
    return move(g.PRSO, WELL_BOTTOM);
  } else if (isVerb(V.CLIMB_UP, V.CLIMB_DOWN, V.CLIMB_FOO)) {
    tell("You can't climb the well.\n");
    return true;
  } else {
    return false;
  }
}

async function MATCH_FCN() {
  let cnt = 0;
  if (isVerb(V.LAMP_ON, V.BURN) && (g.PRSO == MATCH)) {
    if (g.MATCH_COUNT > 0) {
      g.MATCH_COUNT = g.MATCH_COUNT - 1;
    }
    if (!(g.MATCH_COUNT > 0)) {
      tell("I'm afraid you have run out of matches.\n");
      return true;
    } else {
      setFlag(MATCH, FLAMEBIT);
      setFlag(MATCH, ONBIT);
      enable(await QUEUE(I_MATCH.id, 2));
      tell("One of the matches starts to burn.\n");
      return true;
    }
  } else if (isVerb(V.LAMP_OFF) && hasFlag(MATCH, FLAMEBIT)) {
    tell("The match is out.\n");
    clearFlag(MATCH, FLAMEBIT);
    clearFlag(MATCH, ONBIT);
    await QUEUE(I_MATCH.id, 0);
    return true;
  } else if (isVerb(V.COUNT)) {
    tell("You have ");
    cnt = g.MATCH_COUNT - 1;
    tell(N(cnt), " match");
    if (!(cnt == 1)) {
      tell("es.");
    } else {
      tell(".");
    }
    return crlf();
  } else if (isVerb(V.EXAMINE)) {
    if (hasFlag(MATCH, ONBIT)) {
      tell("A match is burning.");
    } else {
      tell("No match is burning.");
    }
    return crlf();
  } else {
    return false;
  }
}

async function I_MATCH() {
  tell("The match has gone out.\n");
  clearFlag(MATCH, FLAMEBIT);
  return clearFlag(MATCH, ONBIT);
}

async function LANTERN() {
  if (isVerb(V.THROW) && (g.PRSO == LAMP)) {
    tell("The lamp has smashed into the floor, and the light has gone out.\n");
    disable(await INT(I_LANTERN.id));
    remove(LAMP);
    return move(BROKEN_LAMP, g.HERE);
  } else if (isVerb(V.LAMP_ON)) {
    if (hasFlag(LAMP, RMUNGBIT)) {
      tell("A burned-out lamp won't light.\n");
      return true;
    } else {
      enable(await INT(I_LANTERN.id));
      return false;
    }
  } else if (isVerb(V.LAMP_OFF)) {
    if (hasFlag(LAMP, RMUNGBIT)) {
      tell("The lamp has already burned out.\n");
      return true;
    } else {
      disable(await INT(I_LANTERN.id));
      return false;
    }
  } else if (isVerb(V.EXAMINE)) {
    if (hasFlag(LAMP, RMUNGBIT)) {
      tell("The lamp has burned out.");
    } else if (hasFlag(LAMP, ONBIT)) {
      tell("The lamp is on.");
    } else {
      tell("The lamp is turned off.");
    }
    return crlf();
  } else {
    return false;
  }
}

async function I_LANTERN() {
  let tick = 0, tbl = g.LAMP_TABLE;
  enable(await QUEUE(I_LANTERN.id, tick = get(tbl, 0)));
  await LIGHT_INT(LAMP, tbl, tick);
  if (!(tick == 0)) {
    return g.LAMP_TABLE = tbl + 4;
  } else {
    return false;
  }
}

async function LIGHT_INT(obj, tbl, tick) {
  if (tick == 0) {
    clearFlag(obj, ONBIT);
    setFlag(obj, RMUNGBIT);
  }
  if ((await HELD$(obj)) || (loc(obj) == g.HERE)) {
    if (tick == 0) {
      tell("You'd better have more light than from the ", D(obj), ".\n");
      return true;
    } else {
      tell(S(get(tbl, 1)), "\n");
      return true;
    }
  } else {
    return false;
  }
}

async function RIDDLE_ROOM_FCN(rarg) {
  if (rarg == M_LOOK) {
    tell("This is a room which is bare on all sides. There is an exit down in the northwest corner of the room. To the east is a great ");
    if (hasFlag(RIDDLE_DOOR, OPENBIT)) {
      tell("open");
    } else {
      tell("closed");
    }
    tell(" door made of stone. Above the stone, the following words are written: \"No man shall pass this door without solving this riddle:\n\n  What is tall as a house,\n    round as a cup,\n      and all the king's horses\n        can't draw it up?\"\n");
    return true;
  } else if (rarg == M_BEG) {
    if (isVerb(V.ANSWER, V.SAY)) {
      if (hasFlag(RIDDLE_DOOR, OPENBIT)) {
        return false;
      } else if (eq(get(g.P_LEXV, g.P_CONT), W.WELL) || eq(get(g.P_LEXV, g.P_CONT + 2), W.WELL)) {
        tell("There is a deafening clap of thunder and the stone door quietly swings open to reveal a passageway beyond.\n");
        await SCORE_UPD(5);
        setFlag(RIDDLE_DOOR, OPENBIT);
      } else {
        tell("A hollow laugh seems to come from the stone door.\n");
      }
      g.P_CONT = false;
      g.QUOTE_FLAG = false;
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function RIDDLE_DOOR_FCN() {
  if (isVerb(V.OPEN)) {
    if (hasFlag(RIDDLE_DOOR, OPENBIT)) {
      tell("It is open!\n");
      return true;
    } else {
      tell("The door can only be opened by answering the riddle.\n");
      return true;
    }
  } else if (isVerb(V.CLOSE)) {
    if (hasFlag(RIDDLE_DOOR, OPENBIT)) {
      tell("Not a chance. The door weighs many tons.\n");
      return true;
    } else {
      tell("It is closed!\n");
      return true;
    }
  } else {
    return false;
  }
}

async function RIDDLE_PSEUDO() {
  if (isVerb(V.EXAMINE)) {
    tell("Use the \"Look\" command.\n");
    return true;
  } else {
    return false;
  }
}

async function MAGIC_ACTOR() {
  let v_ = 0;
  if (g.SPELL$) {
    if (g.SPELL$ == S_FALL) {
      if (isVerb(V.CLIMB_UP, V.CLIMB_DOWN, V.CROSS) || (isVerb(V.WALK) && getPropAddr(g.HERE, P.DOWN))) {
        v_ = getPropAddr(g.HERE, P.GLOBAL);
        if (await ZMEMQB(BRIDGE, v_, propSize(v_))) {
          return (await JIGS_UP("You find yourself drawn toward the edge of the bridge. You peer over the side. Oops, that was clumsy of you! You tripped on something and fell in. Too bad."));
        } else if (25 > random(100)) {
          return (await JIGS_UP("For some odd reason you have tripped on your own feet, or perhaps an invisible cord stretched across the path. The resulting fall seems to have done you in."));
        } else {
          tell("You just tripped on an invisible cord, or perhaps your own feet. But this must be your lucky day, as you managed to regain your balance before what could have been a fatal fall.\n");
          return true;
        }
      } else if (isVerb(V.BOARD)) {
        tell("You get in the ", D(g.PRSO), " but you fall out again, almost as though an invisible hand had tipped it over.\n");
        return true;
      } else {
        return false;
      }
    } else if (g.SPELL$ == S_FLOAT) {
      if (isVerb(V.DIAGNOSE, V.WAIT)) {
        return false;
      } else if (isVerb(V.WALK)) {
        tell("I suppose you plan to do that by flapping your arms?\n");
        return true;
      } else if (isVerb(V.DROP)) {
        move(g.PRSO, g.HERE);
        tell("The ", D(g.PRSO), " drops to the ground.\n");
        return true;
      } else if (isVerb(V.TAKE) && (loc(g.PRSO) == g.HERE)) {
        tell("You can't reach that! It's on the ground.\n");
        return true;
      } else {
        return false;
      }
    } else if (g.SPELL$ == S_FREEZE) {
      if (isVerb(V.DIAGNOSE, V.WAIT)) {
        return false;
      } else {
        tell("You are frozen solid. You might as well wait it out, because you can't do anything else in this state.\n");
        return true;
      }
    } else if ((g.SPELL$ == S_FENCE) && isVerb(V.WALK)) {
      tell("An invisible fence of magical force bars your way.\n");
      return true;
    } else if ((g.SPELL$ == S_FIERCE) && (v_ = await INFESTED$(g.HERE))) {
      if (isVerb(V.ATTACK, V.MUNG)) {
        return false;
      } else {
        await FORCE_FIGHT(v_);
        return true;
      }
    } else if ((g.SPELL$ == S_FERMENT) && isVerb(V.WALK) && (loc(g.WINNER) == g.HERE)) {
      tell("Oops, you seem a little unsteady... I'm not sure you got where you intended going.\n\n");
      return await RANDOM_WALK();
    } else if ((g.SPELL$ == S_FEAR) && (v_ = await INFESTED$(g.HERE))) {
      tell("All at once, you are overcome by fear! There's is a ", D(v_), " in here! Maybe it's after you! ");
      if (hasFlag(loc(g.WINNER), VEHBIT)) {
        tell("You huddle in the corner, terrified.\n");
        return true;
      } else {
        tell("You run from the room screaming in terror!\n\n");
        return await RANDOM_WALK();
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function RANDOM_WALK() {
  let p_ = 0, tx = 0, l = 0, s_ = 0, d_ = false;
  p_ = 0;
  for (;;) {
    if ((p_ = nextProp(g.HERE, p_)) < LOW_DIRECTION) {
      if (d_) {
        s_ = g.SPELL$;
        g.SPELL$ = false;
        g.WINNER = ADVENTURER;
        move(g.WINNER, g.HERE);
        await DO_WALK(d_);
        g.SPELL$ = s_;
      }
      return true;
    } else {
      tx = getPropAddr(g.HERE, p_);
      l = propSize(tx);
      if ((l == UEXIT) || ((l == CEXIT) && globalValue(getb(tx, CEXITFLAG))) || ((l == DEXIT) && hasFlag(getb(tx, DEXITOBJ), OPENBIT))) {
        if (!d_) {
          d_ = p_;
        } else if (50 > random(100)) {
          d_ = p_;
        }
      }
    }
  }
}

async function FORCE_FIGHT(v_) {
  let w_ = 0;
  if (!(w_ = await FIND_IN(ADVENTURER, WEAPONBIT))) {
    w_ = HANDS;
  }
  tell("You are maddened by an overwhelming ferocity, and attack the ", D(v_), " instead.\n");
  return await PERFORM(V.ATTACK, v_, w_);
}

async function DWINDOW_DESC() {
  tell("On the floor is a very small diamond shaped window which is ");
  if (g.DIAMOND_SOLVE) {
    tell("glowing serenely");
  } else {
    tell(S(get(g.DWDESCS, g.DIAMOND_COUNT)));
  }
  tell(".\n");
  return true;
}

async function DWINDOW_FCN() {
  if (isVerb(V.TAKE)) {
    tell("The window is an integral part of the floor.\n");
    return true;
  } else if (isVerb(V.MUNG)) {
    tell("The window is diamond-hard and cannot be broken.\n");
    return true;
  } else if (isVerb(V.EXAMINE, V.LOOK_INSIDE)) {
    return await DWINDOW_DESC();
  } else {
    return false;
  }
}

async function DIAMOND_MOTION(rarg) {
  let dc = 0, dir = 0, rm = 0;
  if (rarg == M_LOOK) {
    tell("This is a room with oddly angled walls and passages in all directions. The walls are made of some glassy substance.\n");
    if (g.HERE == DIAMOND_5) {
      tell("A marble stairway leads upward.");
      if (g.DIAMOND_SOLVE) {
        tell(" The floor has swung down at the end of the stairway to reveal a secret passage leading down into unrelieved darkness.");
      }
      crlf();
    } else {
      await DWINDOW_DESC();
    }
    return true;
  } else if (rarg == M_FLASH) {
    await DWINDOW_DESC();
    return true;
  } else if ((rarg == M_BEG) && isVerb(V.WALK) && !g.DIAMOND_SOLVE) {
    if ((g.HERE == DIAMOND_2 || g.HERE == DIAMOND_4) || (g.HERE == DIAMOND_6 || g.HERE == DIAMOND_8)) {
      dir = get(g.DIDIRS, g.DIAMOND_COUNT - 1);
      if (g.PRSO == dir) {
        g.DIAMOND_COUNT = g.DIAMOND_COUNT + 1;
        if (g.DIAMOND_COUNT > g.DIAMOND_BASE) {
          g.DIAMOND_BASE = g.DIAMOND_COUNT;
          g.DIAMOND_MOVES = 0;
        }
        if (g.DIAMOND_COUNT == 5) {
          tell("You hear a strange rusty squeal echoing in the distance.\n");
          clearFlag(DIAMOND_5, TOUCHBIT);
          await SCORE_UPD(5);
          g.DIAMOND_SOLVE = true;
        }
        if (g.HERE == DIAMOND_2) {
          dir = DIAMOND_4;
        } else if (g.HERE == DIAMOND_4) {
          dir = DIAMOND_8;
        } else if (g.HERE == DIAMOND_8) {
          dir = DIAMOND_6;
        } else if (g.HERE == DIAMOND_6) {
          dir = DIAMOND_2;
        }
        await GOTO(dir);
      } else {
        await DIAMOND_LOSS();
      }
      return true;
    } else if ((g.HERE == DIAMOND_5) && (g.PRSO == P.UP)) {
      return false;
    } else {
      g.DIAMOND_COUNT = 0;
      if (33 > random(100)) {
        tell("There is no way to go in that direction.\n");
        return true;
      } else if (25 > random(100)) {
        await DIAMOND_LOSS();
        return true;
      } else {
        g.DIAMOND_COUNT = 1;
        if (g.DIAMOND_COUNT > g.DIAMOND_BASE) {
          g.DIAMOND_BASE = g.DIAMOND_COUNT;
          g.DIAMOND_MOVES = 0;
        }
        rm = get(g.DIAMOND_ROOMS, random(4) - 1);
        if (hasFlag(BAT, INVISIBLE)) {
          clearFlag(BAT, INVISIBLE);
          move(BAT, rm);
        }
        await GOTO(rm);
        return true;
      }
    }
  } else {
    return false;
  }
}

async function DIAMOND_LOSS() {
  g.DIAMOND_MOVES = g.DIAMOND_MOVES + 1;
  if (g.DIAMOND_MOVES == 20) {
    tell("As you thrash about in the maze, the mirthful voice of the Wizard taunts you: \"Fool! You'll never get past ");
    tell(S(get(g.BASES, g.DIAMOND_BASE)));
    tell(" base at this rate!\"\n");
  }
  return await GOTO(get(g.DIAMOND_ROOMS, 3 + random(5)));
}

async function CERBERUS_FCN() {
  if (isVerb(V.WAVE, V.RUB, V.RAISE) && (g.PRSO == WAND)) {
    tell("The dog looks puzzled.\n");
    return false;
  } else if (g.WAND_ON && isVerb(V.SAY, V.INCANT)) {
    return false;
  } else if (await HELLO$(CERBERUS)) {
    if (g.CERBERUS_LEASHED) {
      tell("\"Arf! Arf! Arf!\"\n");
      return true;
    } else {
      tell("\"Grrrr!\"\n");
      return true;
    }
  } else if (isVerb(V.ATTACK, V.MUNG, V.STAB)) {
    if (g.CERBERUS_LEASHED) {
      remove(CERBERUS);
      tell("With a quiet bark of disappointment, the creature expires. Its six eyes look at you reproachfully. As it dies, it collapses into a small pile of dust which blows away into nothing.\n");
      return true;
    } else if (50 > random(100)) {
      return (await JIGS_UP("The dog-thing snaps at you viciously, and succeeds. Your head, it seems, is only a small mouthful for the poor animal, who is just as hungry afterward."));
    } else {
      tell("The maddened dog-thing snaps viciously at you.\n");
      return true;
    }
  } else if (isVerb(V.PUT, V.PUT_ON) && (g.PRSO == COLLAR)) {
    move(COLLAR, CERBERUS);
    setFlag(COLLAR, NDESCBIT);
    setFlag(COLLAR, TRYTAKEBIT);
    putProp(CERBERUS, P.LDESC, "An insipidly grinning three-headed dog is wagging its tail here. It is wearing a huge dog collar.");
    g.CERBERUS_LEASHED = true;
    tell("The creature whines happily, then the center head licks your face (which is roughly like experiencing a sandpaper washcloth). The other two heads look about, as though the monster felt a sudden need to find a pair of slippers somewhere. Its huge tail wags enthusiastically, knocking small rocks around and almost blowing you over from the breeze it creates.\n");
    return true;
  } else if (isVerb(V.ENCHANT)) {
    if (g.SPELL_USED == W.FLOAT) {
      g.SPELL_HANDLED$ = true;
      tell("The huge dog rises about an inch off the ground, for a moment.\n");
      return true;
    } else if (g.SPELL_USED == W.FIERCE) {
      g.SPELL_HANDLED$ = true;
      return (await JIGS_UP("Cerberus tears you limb from limb! What ferocity!"));
    } else if (g.SPELL_USED == W.FEEBLE) {
      tell("What an effect! He now has the strength of just one elephant, rather than ten!\n");
      return true;
    } else {
      return false;
    }
  } else if (!g.CERBERUS_LEASHED) {
    tell("The three-headed dog snaps at you viciously!\n");
    return true;
  } else if (g.CERBERUS_LEASHED && isVerb(V.RUB)) {
    tell("The dog is now insanely happy, slobbering all over the place and whining with uncontained doggish joy.\n");
    return true;
  } else {
    return false;
  }
}

async function COLLAR_FCN() {
  if (isVerb(V.TAKE) && g.CERBERUS_LEASHED) {
    return (await JIGS_UP("That wasn't such a good idea. The creature was enjoying being your pet. As you unfasten the collar, the disappointed monster hound begins to growl, and then its three fang-crammed mouths rend you into little doggy biscuits."));
  } else if (isVerb(V.ENCHANT) && (g.SPELL_USED == W.FLOAT)) {
    await PERFORM(V.ENCHANT, CERBERUS);
    return true;
  } else {
    return false;
  }
}

async function GLACIER_FCN() {
  if (isVerb(V.MELT)) {
    tell("This is a big glacier; you'll need a lot of heat.\n");
    return true;
  } else {
    return false;
  }
}

async function GLACIER_ROOM_FCN(rarg) {
  if (rarg == M_LOOK) {
    tell("This is a large hall of ancient lava, since worn smooth by the movement of a glacier. A large passage exits to the east and an upward lava tube is at the top of a jumble of fallen rocks.\n");
    if (g.ICE_MELTED) {
      tell("A damp and scorched passage leads west. It is still partly full of steam.\n");
    }
    return true;
  } else {
    return false;
  }
}

async function DRAGON_FCN() {
  let $1;
  enable(await QUEUE(I_DRAGON.id, -1));
  if (await HELLO$(DRAGON)) {
    tell("The dragon looks amused. He speaks in a voice so deep you feel it rather than hear it, but the tongue is unknown to you. You find yourself almost hypnotized.\n");
    return g.DRAGON_ANGER = g.DRAGON_ANGER + 2;
  } else if (isVerb(V.EXAMINE)) {
    tell("He turns and looks back at you, his cat's eyes yellow in the gloom. You start to feel weak, and quickly turn away.\n");
    return g.DRAGON_ANGER = g.DRAGON_ANGER + 1;
  } else if (isVerb(V.ATTACK, V.MUNG, V.KICK, V.LAMP_ON)) {
    if (isVerb(V.LAMP_ON) || (isVerb(V.ATTACK) && !g.PRSI)) {
      tell("With your bare hands? I doubt the dragon even noticed.\n");
    } else {
      $1 = await RANDOM_ELEMENT(g.DRAGON_ATTACKS);
      tell(S($1));
      tell("\n");
    }
    return g.DRAGON_ANGER = g.DRAGON_ANGER + 4;
  } else if (isVerb(V.GIVE) && (g.PRSI == DRAGON)) {
    g.DRAGON_ANGER = g.DRAGON_ANGER + 1;
    if (getPropAddr(g.PRSO, P.VALUE)) {
      move(g.PRSO, CHEST);
      tell("The dragon is pleased by your gift, excuses himself for a moment, and returns without it.\n");
      return true;
    } else if (await BOMB$(g.PRSO)) {
      g.DRAGON_ANGER = g.DRAGON_ANGER + 2;
      remove(BRICK);
      tell("The dragon snakes his long red tongue around the bomb and politely swallows it. A few moments later he belches and smoke curls out of his nostrils.\n");
      return true;
    } else {
      tell("The dragon refuses your gift.\n");
      return true;
    }
  } else if (isVerb(V.WALK) && (g.HERE == DRAGON_ROOM) && (g.PRSO == P.NORTH)) {
    g.DRAGON_ANGER = g.DRAGON_ANGER + 3;
    tell("The dragon puts out a claw, grins (all of his sword-sharp teeth glinting in the light), and blocks your way.\n");
    return true;
  } else {
    return false;
  }
}

async function HELLO$(who) {
  if ((g.WINNER == who) || isVerb(V.TELL, V.ANSWER, V.REPLY, V.SAY, V.HELLO, V.INCANT)) {
    if (isVerb(V.TELL, V.ANSWER, V.SAY, V.INCANT, V.REPLY)) {
      g.P_CONT = false;
      g.QUOTE_FLAG = false;
    }
    return true;
  } else {
    return false;
  }
}

async function FIND_TARGET(target) {
  let p_ = 0, tx = 0, l = 0, room = 0;
  if (loc(target) == g.HERE) {
    return g.HERE;
  } else {
    p_ = 0;
    for (;;) {
      if ((p_ = nextProp(g.HERE, p_)) == 0) {
        return false;
      } else if (!(p_ < LOW_DIRECTION)) {
        tx = getPropAddr(g.HERE, p_);
        l = propSize(tx);
        if (l == UEXIT || l == CEXIT || l == DEXIT) {
          room = getb(tx, 0);
          if (loc(target) == room) {
            return room;
          }
        }
      }
    }
  }
}

async function I_DRAGON() {
  let room = 0;
  if (g.DRAGON_ANGER > 6) {
    tell("The dragon tires of this game. With an almost bored yawn, he opens his mouth and ");
    if (g.SPELL$ == S_FIREPROOF) {
      tell("blasts you with a great gout of fire, but it washes over you harmlessly.\n");
    } else {
      await DRAGON_LEAVES();
      (await JIGS_UP("incinerates you in a blast of white-hot dragon fire."));
    }
  } else if ((loc(g.WINNER) == DRAGON_ROOM) && !(loc(DRAGON) == DRAGON_ROOM)) {
    move(DRAGON, DRAGON_ROOM);
    tell("The dragon doubles back and charges into the room, maddened by your attempt to sneak past him. His eyes glow with a white heat of anger.\n");
    if (g.SPELL$ == S_FIREPROOF) {
      (await JIGS_UP("A huge ball of flame envelops you, but you don't even feel the heat. The dragon is puzzled, but not too puzzled to crush you in his jaws."));
    } else {
      (await JIGS_UP("Worse for you, his mouth opens and a great gout of flame puffs out and consumes you on the spot."));
    }
  } else if (!(g.DRAGON_ANGER > 0)) {
    if ((50 > random(100)) && (loc(DRAGON) == g.HERE)) {
      tell("The dragon looks bored.\n");
    } else {
      await DRAGON_LEAVES();
      if (g.HERE == GLACIER_ROOM) {
        tell("The dragon is no longer around. He must have become bored with you.\n");
      } else if (g.HERE == g.OLD_HERE) {
        tell("The dragon seems to have lost interest in you.");
        if (g.OLD_HERE == DRAGON_ROOM) {
          crlf();
        } else {
          tell(" He wanders off.\n");
        }
      }
    }
  } else {
    room = await FIND_TARGET(g.WINNER);
    if (!room) {
      if (25 > random(100)) {
        await DRAGON_LEAVES();
      }
    } else if ((room == CAROUSEL_ROOM || room == TINY_ROOM) || (room == RAVINE_LEDGE || room == FRESCO_ROOM)) {
      if (25 > random(100)) {
        await DRAGON_LEAVES();
      }
      tell("The dragon will follow no further.\n");
    } else if (room == GLACIER_ROOM) {
      tell("\nAs the dragon enters, he sees his reflection on the icy surface of the glacier at its western end. He becomes enraged: There is another dragon here, behind that glass, he thinks! Dragons are smart, but sometimes naive, and this one has never seen ice before. He rears up to his full height to challenge this intruder into his territory. He roars a challenge! The intruder responds! The dragon takes a deep breath, and out of his mouth pours a massive gout of flame. It washes over the ice, which melts rapidly, sending out torrents of water and a huge cloud of steam! You manage to clamber up to a small shelf, but the dragon is terrified! A huge splash goes down his throat! There is a muffled explosion and the dragon, a puzzled expression on his face, dies. He is carried away by the water.\n\nWhen the flood recedes you climb gingerly down. While no trace of the dragon can be found, the melting of the ice has revealed a passage leading west.\n");
      remove(DRAGON);
      remove(ICE);
      move(DEAD_DRAGON, DEEP_FORD);
      disable(await INT(I_DRAGON.id));
      await SCORE_UPD(5);
      g.ICE_MELTED = true;
    } else {
      if (!(room == g.OLD_HERE)) {
        move(DRAGON, room);
        tell("The dragon follows you, out of mingled curiosity and anger.\n");
      } else {
        tell("The dragon continues to watch you carefully.\n");
      }
      if (!(g.DRAGON_ANGER > 0)) {
        g.DRAGON_ANGER = 0;
        disable(await INT(I_DRAGON.id));
      }
    }
  }
  g.OLD_HERE = loc(DRAGON);
  g.DRAGON_ANGER = g.DRAGON_ANGER - 2;
  if (g.DRAGON_ANGER < 0) {
    g.DRAGON_ANGER = 0;
  }
  return true;
}

async function DRAGON_LEAVES() {
  if (!(loc(DEAD_DRAGON))) {
    move(DRAGON, DRAGON_ROOM);
    g.DRAGON_ANGER = 0;
    return disable(await INT(I_DRAGON.id));
  } else {
    return false;
  }
}

