async function STAND_FCN() {
  if (isVerb(V.TAKE)) {
    tell("The ", D(g.PRSO), " is firmly attached to the bench.\n");
    return true;
  } else if (isVerb(V.PUT, V.PUT_ON) && (g.PRSO == PALANTIR_1 || g.PRSO == PALANTIR_2 || g.PRSO == PALANTIR_3) && (g.PRSI == STAND_1 || g.PRSI == STAND_2 || g.PRSI == STAND_3)) {
    await V_PUT();
    if ((loc(PALANTIR_1) == STAND_1) && (loc(PALANTIR_2) == STAND_2) && (loc(PALANTIR_3) == STAND_3)) {
      remove(PALANTIR_1);
      remove(PALANTIR_2);
      remove(PALANTIR_3);
      move(STAND_4, WORKBENCH);
      tell("As you place the ", D(g.PRSO), " in the ", D(g.PRSI), ", a low humming noise begins, and you can feel the hairs on the back of your neck begin to stand up. The three spheres begin to vibrate, faster and faster, as the noise becomes higher and higher pitched. Three puffs of smoke, one red, one blue, one white, rise up from empty stands. The spheres are gone! But in the center of the triangle formed by the stands is now a black stand of obsidian in which rests a strange black sphere.\n");
    }
    return true;
  } else {
    return false;
  }
}

async function IN_AQUARIUM_FCN(rarg) {
  if (rarg == M_LOOK) {
    tell("There is a sandy floor here, and your vision seems murky and blurred. The wall you are looking at is nicely dressed stone.\n");
    if (loc(SERPENT) == AQUARIUM) {
      if (25 > random(100)) {
        tell("While you watch a shadow seems to pass overhead.\n");
      } else if (5 > random(100)) {
        tell("The head of some horrible serpent pokes into view, its beady green eyes almost seeming to see you.\n");
      }
    }
    return true;
  } else if (rarg == M_ENTER) {
    if (loc(SERPENT) == AQUARIUM) {
      return (await JIGS_UP("You drop into the aquarium with a splash (which attracts the serpent). He greedily eats you. He's just a baby, after all, and needs all the food he can get."));
    } else {
      return (await JIGS_UP("Oh dear, you have cut yourself severely on the broken glass. I'm afraid you've bled to death."));
    }
  } else {
    return false;
  }
}

async function AQUARIUM_FCN() {
  let obj = 0;
  if (isVerb(V.BOARD, V.THROUGH)) {
    await DO_WALK(P.IN);
    return true;
  } else if (isVerb(V.LOOK_INSIDE) && (loc(SERPENT) == AQUARIUM)) {
    tell("In the aquarium is a baby sea-serpent who eyes you suspiciously. His scaly body writhes about in the huge tank.\n");
    return true;
  } else if ((isVerb(V.MUNG, V.ATTACK) && (g.PRSO == AQUARIUM)) || (isVerb(V.THROW) && (g.PRSI == AQUARIUM))) {
    if (g.PRSO == AQUARIUM) {
      if (!g.PRSI) {
        return false;
      } else {
        obj = g.PRSI;
      }
    } else {
      obj = g.PRSO;
    }
    move(obj, g.HERE);
    if (loc(DEAD_SERPENT) == g.HERE) {
      tell("The aquarium is already broken!\n");
      return true;
    } else if (obj == FLASK) {
      (await JIGS_UP("The flask shatters, and poison gas fills the room!"));
      return true;
    } else if (await BOMB$(obj)) {
      return disable(await INT(I_FUSE.id));
    } else if (hasFlag(obj, WEAPONBIT) || (getProp(obj, P.SIZE) > 10)) {
      remove(SERPENT);
      move(PALANTIR_3, AQUARIUM);
      clearFlag(PALANTIR_3, NDESCBIT);
      putProp(AQUARIUM, P.LDESC, "A shattered aquarium fills the northern half of the room.");
      move(DEAD_SERPENT, g.HERE);
      tell("The ", D(obj), " shatters the glass wall of the aquarium, spilling out an impressive amount of salt water and wet sand. It also spills out an extremely annoyed sea serpent who bites angrily at the ", D(obj), ", and then at you. He is having difficulty breathing, and he seems to hold you responsible for his current problem.");
      if (isVerb(V.MUNG)) {
        tell(" He manages to rend you limb from limb before he drowns in the air.\n");
        return (await JIGS_UP("I guess you were too careless."));
      } else {
        tell(" He tries to slither across the stone floor towards you. Fortunately, he expires mere inches away from biting off your foot. A clear crystal sphere sits amid the sand and broken glass on the bottom of the aquarium.\n");
        return true;
      }
    } else {
      tell("The ", D(obj), " bounces harmlessly off the glass.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function SERPENT_FCN() {
  if (SERPENT == g.WINNER) {
    tell("The serpent only stares hungrily at you.\n");
    return true;
  } else if (isVerb(V.ATTACK, V.MUNG)) {
    tell("He swims towards you with a powerful stroke of his flippers, dagger-like teeth dripping. Fortunately, he doesn't want to crash into the aquarium wall, and contents himself with splashing you with water.\n");
    return true;
  } else if (isVerb(V.PUT) && (g.PRSO == SERPENT)) {
    tell("Impossible for many reasons.\n");
    return true;
  } else if (isVerb(V.TAKE, V.GIVE)) {
    return (await JIGS_UP("He takes you instead. *Uurrp!*"));
  } else {
    return false;
  }
}

async function DEAD_SERPENT_FCN() {
  if (isVerb(V.TAKE)) {
    tell("This may only be a baby sea serpent, but it's as big as a small whale.\n");
    return true;
  } else {
    return false;
  }
}

async function GENIE_FCN(rarg = M_OBJECT) {
  let v_ = 0, hoard = 0;
  if (isVerb(V.HELLO)) {
    tell("The genie grins demonically, but says nothing.\n");
    return true;
  } else if (g.WINNER == GENIE) {
    if (!g.GENIE_READY$) {
      tell("\"My fee is not paid! I perform no tasks for free! We demons have a strong union these days.\"\n");
      return M_FATAL;
    } else if (isVerb(V.SGIVE)) {
      return false;
    } else if ((get(g.P_PRSO, 0) > 1) || (get(g.P_PRSI, 0) > 1)) {
      tell("\"I will do one thing only, oh gracious master!\"\n");
      return M_FATAL;
    } else if (isVerb(V.MOVE) && (g.PRSO == GLOBAL_MENHIR)) {
      g.MENHIR_POSITION = 1;
      tell("The demon is gone for a moment. \"A trifle... My little finger alone was enough.\"\n");
      return await GENIE_LEAVES();
    } else if (isVerb(V.TAKE)) {
      if (g.PRSO == GLOBAL_MENHIR) {
        remove(MENHIR);
        g.MENHIR_POSITION = 2;
        tell("The demon flashes away for a second. \"I have little use for such a thing, but perhaps as a doorstop...\"\n");
        return await GENIE_LEAVES();
      } else if (g.PRSO == WAND) {
        tell("\"This I do gladly, oh fool!\" cackles the demon gleefully. He stretches out an enormous hand towards the wand and taking it like a toothpick (this is a large demon), points it at himself. \"Free!\" he commands, and the demon and his wand vanish forever.\n");
        await GENIE_LEAVES(false);
        return remove(WAND);
      } else if (hasFlag(g.PRSO, TAKEBIT)) {
        await GENIE_LEAVES(false);
        remove(g.PRSO);
        tell("The demon snaps his fingers, the ", D(g.PRSO), " spins wildly in the air in front of him, then he and it depart.\n");
        return true;
      } else {
        tell("\"I fear that I cannot take such a thing.\"\n");
        return true;
      }
    } else if (isVerb(V.GIVE) && (g.PRSI == ME)) {
      if (g.PRSO == WAND) {
        tell("\"I hear and obey!\" says the demon. He stretches out an enormous hand towards the wand. The Wizard is unsure what to do, pointing it threateningly at the demon, then at you. \"Fudge!\" he cries, but aside from a strong odor of chocolate in the air, there is no effect. The demon plucks the wand out of his hand (it's about toothpick-size to him) and gingerly lays it before you. He fades into the smoke, which disperses. The wizard runs from the room in terror.\n");
        remove(WIZARD);
        await GENIE_LEAVES(false);
        clearFlag(WAND, NDESCBIT);
        return move(WAND, g.HERE);
      } else if (g.PRSO == GLOBAL_MENHIR) {
        move(MENHIR, PENTAGRAM_ROOM);
        clearFlag(MENHIR, NDESCBIT);
        clearFlag(MENHIR, TAKEBIT);
        g.MENHIR_POSITION = 3;
        tell("He waves his hands, and the menhir drops softly at your feet.\n");
        return await GENIE_LEAVES();
      } else if (hasFlag(g.PRSO, TAKEBIT)) {
        move(g.PRSO, PENTAGRAM_ROOM);
        tell("The ", D(g.PRSO), " appears before you and settles to the ground.\n");
        return await GENIE_LEAVES();
      } else {
        tell("\"Were it possible, this would be my fondest wish, but alas...\"\n");
        return true;
      }
    } else if (isVerb(V.ATTACK)) {
      if (g.PRSO == GLOBAL_CERBERUS) {
        tell("\"This may prove taxing, but we'll see. Perhaps I'll tame him for a pup instead.\" The demon disappears for an instant, then reappears. He looks rather gnawed and scratched. He winces. \"Too much for me. Puppy dog, indeed. You're welcome to him. Never did like dogs anyway... Any other orders, oh beneficent one?\"\n");
        return true;
      } else if (g.PRSO == WIZARD) {
        tell("The demon grins hideously. \"This has been my desire e'er since this charlatan bent me to his service. I perform this deed with pleasure!\" The demon forms himself back into a cloud of greasy smoke. The cloud envelops the Wizard, who waves his wand fruitlessly, mumbling various phrases which begin with \"F\". A horrible scream is heard, and the smoke begins to clear. Nothing remains of the Wizard but his wand.\n");
        remove(WIZARD);
        clearFlag(WAND, NDESCBIT);
        move(WAND, g.HERE);
        return await GENIE_LEAVES();
      } else if (g.PRSO == ME) {
        await GENIE_LEAVES(false);
        g.WINNER = ADVENTURER;
        return (await JIGS_UP("\"Foolish mortal, if you insist...\" The demon crushes you with one blow of his enormous hand."));
      } else {
        tell("\"I know no way to kill a ", D(g.PRSO), ".\"\n");
        return true;
      }
    } else if (isVerb(V.FIND, V.EXAMINE)) {
      tell("\"I am not permitted to ");
      if (isVerb(V.FIND)) {
        tell("answer questions");
      } else {
        tell("perform such menial tasks");
      }
      tell(". The terms of my contract are explicit on this matter, learned one. Surely you would not wish to violate my contract?\" He licks his lips with a forked tongue like a snake's. \"The penalty clauses are ... hmm ... devilish.\"\n");
      return true;
    } else {
      tell("\"Apologies, oh master, but even for such a one as I this is not possible.\" He seems somewhat chagrined to have to admit this.\n");
      return true;
    }
  } else if (isVerb(V.EXORCISE, V.ATTACK, V.MUNG)) {
    tell("The demon laughs uproariously.\n");
    return true;
  } else if (isVerb(V.GIVE) && (g.PRSI == GENIE)) {
    if ((g.PRSO == IRON_BOX) && (loc(VIOLIN) == g.PRSO)) {
      tell("The genie frowns briefly, then ");
      if (hasFlag(g.PRSO, OPENBIT)) {
        tell("looks inside");
      } else {
        tell("opens");
      }
      tell(" the box. He smiles horribly.\n");
      await REMOVE_CAREFULLY(IRON_BOX);
      g.PRSO = VIOLIN;
    }
    if (getPropAddr(g.PRSO, P.VALUE) && !(g.PRSO == SWORD)) {
      await REMOVE_CAREFULLY(g.PRSO);
      g.GENIE_HOARD = g.GENIE_HOARD + 1;
      await SCORE_UPD(2);
      hoard = g.GENIE_HOARD + (await CASE_WORTH());
      if (!(hoard < TREASURES_MAX)) {
        g.GENIE_READY$ = true;
        putProp(WIZARD, P.LDESC, "A dejected and fearful Wizard watches from the corner.");
        tell("\"This will do for my fee. 'Tis a paltry hoard, but as you have done me a small service by loosing me from this wizard, it will suffice.\"\n");
        return true;
      } else {
        tell("\"", S(get(g.GENIE_THANKS, hoard)), "\"\n");
        if (hoard == 8) {
          tell("The Wizard looks at you as if you are a madman. He tears his beard and stares at you fearfully.\n");
        }
        return true;
      }
    } else if (await BOMB$(g.PRSO)) {
      await GENIE_LEAVES(false);
      tell("\"I fear that this violates my contract, oh foolish one. Thus, I am free to depart.\"\n");
      return true;
    } else {
      await REMOVE_CAREFULLY(g.PRSO);
      tell("The demon gladly takes the ", D(g.PRSO), " and smiles balefully, revealing enormous fangs.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function GENIE_LEAVES(noisy$ = true) {
  setFlag(GENIE, INVISIBLE);
  if (noisy$) {
    tell("The genie departs, his agreement fulfilled.\n");
  }
  g.P_CONT = false;
  return M_FATAL;
}

async function CASE_WORTH() {
  let f = 0, w_ = 0;
  f = first(WIZARD_CASE);
  for (;;) {
    if (!f) {
      return w_;
    }
    if (getPropAddr(f, P.VALUE)) {
      w_ = w_ + 1;
    }
    f = next(f);
  }
}

async function PENTAGRAM_FCN(rarg = M_BEG) {
  if (rarg == M_BEG) {
    if (isVerb(V.THROUGH, V.BOARD)) {
      tell("You try to enter the pentagram, but are forced back by an invisible power.\n");
      return true;
    } else if (isVerb(V.PUT, V.PUT_ON) && (g.PRSO == PALANTIR_4)) {
      remove(PALANTIR_4);
      clearFlag(GENIE, INVISIBLE);
      move(GENIE, PENTAGRAM_ROOM);
      tell("A cold wind blows outward from the sphere. The candles flicker, and a low moan, almost inaudible, is heard. It rises in volume and pitch until it becomes a high-pitched keening. A dim shape becomes visible in the air above the sphere. The shape resolves into a large and somewhat formidable looking demon. He looks around, tests the walls of the pentagram experimentally, then sees you! \"Hmm, a new master...\" he says under his breath. \"Greetings, oh master! Wouldst desire a service, as our contract stateth? For some pittance of wealth, some trifle, I will gratify thy desires to the utmost limit of my powers, and they are not inconsiderable.\" He makes a pass with his massive arms and the walls begin to shake a little. Another pass and the shaking stops. \"A nice effect... I find it makes for a better relationship to give such a demonstration early on.\" He grins vilely.\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function WIZARD_FCN(rarg = M_OBJECT) {
  let olit = 0;
  if (g.WINNER == WIZARD) {
    if (isVerb(V.GIVE)) {
      tell("The Wizard replies \"Foolishment!\"\n");
      return true;
    } else {
      tell("The Wizard considers your statement carefully. His expression indicates he regards it as fanciful.\n");
      return true;
    }
  } else if (isVerb(V.GIVE) && (g.PRSI == WIZARD)) {
    olit = g.LIT;
    await REMOVE_CAREFULLY(g.PRSO);
    if (await BOMB$(g.PRSO)) {
      if (loc(GENIE) == PENTAGRAM_ROOM) {
        move(g.PRSO, g.HERE);
        tell("The wizard accepts this final folly resignedly.\n");
        return true;
      } else {
        remove(WIZARD);
        tell("\"Hmm...\" The Wizard mutters something, then waves his wand over the bomb. It transforms into a bouquet of flowers. Both Wizard and flowers disappear.\n");
        return true;
      }
    } else if (olit && !g.LIT) {
      tell("\"Thank you.\" As the Wizard places the ", D(g.PRSO), " under his robe, the room becomes dark.\n");
      return true;
    } else {
      tell("\"Thank you.\"\n");
      return true;
    }
  } else if (await HELLO$(WIZARD)) {
    tell("The Wizard seems surprised, much as you might be if a dog talked.\n");
    return true;
  } else if (isVerb(V.ATTACK, V.MUNG)) {
    remove(WIZARD);
    if (loc(WAND) == WIZARD) {
      tell("The Wizard retreats, waving his wand and chanting. He says \"Fear!\" ");
    } else {
      tell("The Wizard tries to cast the \"Fear!\" spell, but without his wand! ");
    }
    if (!(hasFlag(GENIE, INVISIBLE))) {
      tell("Nothing happens! With a terrified glance at the demon, the wizard runs past you and out of the room.\n");
      return true;
    } else {
      tell("You are suddenly terrified. The Wizard seems huge and terrible, looming over you. You flee, terrified. He chuckles, snaps his fingers, and disappears.\n\n");
      g.SPELL$ = S_FEAR;
      putProp(ADVENTURER, P.ACTION, MAGIC_ACTOR.id);
      enable(await QUEUE(I_WIZARD.id, 10));
      return await RANDOM_WALK();
    }
  } else {
    return false;
  }
}

async function I_WIZARD() {
  let cast_prob = 0, pcnt = 0, f = 0, wloc = loc(g.WINNER);
  let $1;
  enable(await QUEUE(I_WIZARD.id, 4));
  if (g.DEAD) {
    return false;
  } else if (g.SPELL$) {
    if (g.SPELL$ == S_FLOAT) {
      if (g.HERE == WELL_TOP) {
        (await JIGS_UP("You plunge to the bottom of the shaft as the spell wears off."));
        return true;
      } else if (hasFlag(g.HERE, NONLANDBIT) && !(g.HERE == WELL_BOTTOM || g.HERE == VOLCANO_BOTTOM)) {
        (await JIGS_UP("As the spell wears off, you find yourself making a half-gainer towards the bottom of the volcano."));
        return true;
      }
    } else if (g.SPELL$ == S_FEEBLE) {
      g.LOAD_ALLOWED = g.LOAD_MAX;
    } else if (g.SPELL$ == S_FIERCE) {
      g.SWORD_GLOW = 0;
    } else if (g.SPELL$ == S_FUMBLE) {
      g.FUMBLE_NUMBER = 7;
      g.FUMBLE_PROB = 8;
    }
    if (get(g.SPELL_STOPS, g.SPELL$)) {
      tell(S(get(g.SPELL_STOPS, g.SPELL$)), "\n");
    }
    putProp(ADVENTURER, P.ACTION, 0);
    g.SPELL$ = false;
    return true;
  }
  if (loc(GENIE) == PENTAGRAM_ROOM) {
    disable(await INT(I_WIZARD.id));
    if (!(loc(WIZARD) == PENTAGRAM_ROOM)) {
      move(WIZARD, PENTAGRAM_ROOM);
      if (loc(g.WINNER) == PENTAGRAM_ROOM) {
        tell("Suddenly the Wizard materializes in the room. He is astonished by what he sees: his servant in deep conversation with a common adventurer! He draws forth his wand, waves it frantically, and incants \"Frobizz! Frobozzle! Frobnoid!\" The demon laughs heartily. \"You no longer control the Black Crystal, hedge-wizard! Your wand is powerless! Your doom is sealed!\" The demon turns to you, expectantly.\n");
      }
    }
    return true;
  }
  if (!g.LIT && hasFlag(LAMP, RMUNGBIT) && (g.SCORE > 200)) {
    g.ALWAYS_LIT = true;
    g.LIT = true;
    tell("In the darkness you hear the voice of the Wizard. \"Dear me, you seem to have gotten into quite a pickle.\" He chuckles. \"Fluoresce!\" he incants. It is no longer dark.\n");
    return true;
  }
  if (loc(WIZARD) && (80 > random(100))) {
    if (g.LIT && (loc(WIZARD) == g.HERE)) {
      tell("The Wizard vanishes.\n");
    }
    remove(WIZARD);
    return true;
  }
  if (10 > random(100)) {
    if (!g.LIT) {
      tell("You feel a slight outrush of air as something moves nearby.\n");
    } else if (g.HERE == POSTS_ROOM || g.HERE == POOL_ROOM) {
      tell("A huge and terrible wizard appears before you, as large as the largest tree! He looks down on you as you would look upon a gnat!\n");
    } else if (hasFlag(g.HERE, NONLANDBIT)) {
      tell("The Wizard appears, floating nonchalantly in the air beside you. He grins sideways at you.\n");
    } else {
      tell("A strange little man in a long cloak appears suddenly in the room. He is wearing a high pointed hat embroidered with astrological signs. He has a long, stringy, and unkempt beard.\n");
    }
    if (loc(PALANTIR_4) == ADVENTURER) {
      if (g.LIT) {
        tell("The Wizard notices that you carry the Black Crystal, and with an unseemly haste, he disappears.\n");
      } else {
        tell("You feel a sudden inrush of air as though something disappeared.\n");
      }
      remove(WIZARD);
      return true;
    } else if (20 > random(100)) {
      if (g.LIT) {
        tell("He mutters something (muffled by his beard) and disappears as suddenly as he came.\n");
      } else {
        tell("You hear low, confused muttering.\n");
      }
      remove(WIZARD);
      return true;
    }
    if (loc(PALANTIR_1) == ADVENTURER) {
      pcnt = pcnt + 1;
    }
    if (loc(PALANTIR_2) == ADVENTURER) {
      pcnt = pcnt + 1;
    }
    if (loc(PALANTIR_3) == ADVENTURER) {
      pcnt = pcnt + 1;
    }
    cast_prob = 80 - (pcnt * 20);
    if (g.LIT) {
      tell("The Wizard draws forth his wand and waves it in your direction. It begins to glow with a faint blue glow.\n");
    } else {
      tell("Suddenly, illuminated by the faint blue glow of a magic wand pointed in your direction, you see the Wizard!\n");
    }
    if (cast_prob > random(100)) {
      move(WIZARD, g.HERE);
      g.SPELL$ = random(SPELLS);
      putProp(ADVENTURER, P.ACTION, MAGIC_ACTOR.id);
      enable(await QUEUE(I_WIZARD.id, 5 + random(30 - (5 * pcnt))));
      if (75 > random(100)) {
        tell("The Wizard, in a deep and resonant voice, speaks the word \"", S(get(g.SPELL_NAMES, g.SPELL$)), "!\" He then vanishes, cackling gleefully.\n");
      } else {
        tell("The Wizard, almost inaudibly, whispers a word beginning with \"F,\" and then disappears, chuckling nastily.\n");
      }
      remove(WIZARD);
      if (get(g.SPELL_HINTS, g.SPELL$)) {
        tell(S(get(g.SPELL_HINTS, g.SPELL$)), "\n");
      }
      if (g.SPELL$ == S_FALL) {
        if (hasFlag(wloc, VEHBIT)) {
          tell("You suddenly fall headlong out of the ", D(wloc), " as though someone had flipped it over.\n");
          if (g.HERE == WELL_TOP) {
            (await JIGS_UP("You plummet to the bottom of the shaft."));
          } else if (hasFlag(g.HERE, NONLANDBIT) && !(g.HERE == VOLCANO_BOTTOM || g.HERE == WELL_BOTTOM)) {
            (await JIGS_UP("You make a rather messy swan dive to the bottom of the volcano."));
          } else {
            move(g.WINNER, g.HERE);
          }
        }
      } else if (g.SPELL$ == S_FLOAT) {
        if (hasFlag(wloc, VEHBIT)) {
          tell(" You rise majestically out of the ", D(wloc), ", coming to a stop about five feet above it and to one side.\n");
          move(g.WINNER, g.HERE);
        } else {
          tell("Slowly, you and all your belongings rise into the air, stopping after about five feet.\n");
        }
      } else if (g.SPELL$ == S_FEEBLE) {
        g.LOAD_ALLOWED = 50;
        if (f = first(g.WINNER)) {
          tell("In fact, you feel so weak that you drop the ", D(f), ".\n");
          move(f, wloc);
        }
      } else if (g.SPELL$ == S_FEAR) {
        if (hasFlag(wloc, VEHBIT)) {
          tell("You cower in the corner of the ", D(wloc), ", hoping the wizard won't see you.\n");
        } else {
          crlf();
          await RANDOM_WALK();
        }
      } else if (g.SPELL$ == S_FUMBLE) {
        g.FUMBLE_NUMBER = 3;
        g.FUMBLE_PROB = 25;
        if (f = first(ADVENTURER)) {
          tell("Ooops! You dropped the ", D(f), ".\n");
          move(f, wloc);
        }
      } else if (g.SPELL$ == S_FILCH) {
        if (await ROB(g.WINNER, WIZARD_CASE)) {
          tell("Something you are carrying has disappeared!\n");
        }
      } else if (g.SPELL$ == S_FIERCE) {
        tell("The Wizard mumbles something under his breath, and just before you reach him, he vanishes.\n");
      }
      return true;
    } else if (50 > random(100)) {
      remove(WIZARD);
      tell("There is a loud crackling noise. Blue smoke rises from out of the Wizard's sleeve. He sighs and disappears.\n");
      return true;
    } else if (50 > random(100)) {
      remove(WIZARD);
      tell("The Wizard incants \"");
      $1 = await RANDOM_ELEMENT(g.SPELL_NAMES);
      tell(S($1));
      tell("!\" but nothing happens. He shakes the wand. Nothing happens. With a slightly embarrassed glance in your direction, he vanishes.\n");
      return true;
    } else {
      move(WIZARD, g.HERE);
      tell("The Wizard seems about to say something, but thinks better of it, and peers at you from under his bushy eyebrows.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function ROB(who, where) {
  let n_ = 0, x = 0, robbed$ = false;
  x = first(who);
  for (;;) {
    if (!x) {
      return robbed$;
    }
    n_ = next(x);
    if (await RIPOFF(x, where)) {
      robbed$ = true;
    }
    x = n_;
  }
}

async function RIPOFF(x, where) {
  if (!(hasFlag(x, INVISIBLE)) && getPropAddr(x, P.VALUE) && !(x == PALANTIR_1) && !(x == PALANTIR_2) && !(x == PALANTIR_3) && !(x == GOLD_KEY) && !(x == CANDY)) {
    move(x, where);
    setFlag(x, TOUCHBIT);
    return true;
  } else {
    return false;
  }
}

async function WIZARD_CASE_FCN() {
  if (g.WINNER == GENIE) {
    if (isVerb(V.MUNG, V.OPEN)) {
      remove(WIZARD_CASE);
      move(BROKEN_CASE, TROPHY_ROOM);
      tell("The demon smashes the case into smithereens. Everything in it smashes as well.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.ENCHANT) && (g.SPELL_USED == W.FILCH)) {
    await ROB(WIZARD_CASE, g.HERE);
    g.SPELL_HANDLED$ = true;
    tell("The contents of the case are arrayed at your feet.\n");
    return true;
  } else if (isVerb(V.OPEN, V.MUNG, V.CLOSE, V.TAKE)) {
    tell("The case is protected by a fearful spell. You cannot touch it in any way.\n");
    return true;
  } else {
    return false;
  }
}

async function WAND_FCN() {
  if (isVerb(V.TAKE, V.PUT, V.GIVE) && (loc(WAND) == WIZARD)) {
    if (g.WINNER == ADVENTURER) {
      tell("The Wizard snatches it away.\n");
      return true;
    } else if (g.WINNER == ROBOT) {
      return (await JIGS_UP("The Wizard snatches the wand away, muttering the word \"Float\" at the robot. Unfortunately he has no floating-point processor and dies in a vain attempt to divide 4.85 by 3.62."));
    } else {
      return false;
    }
  } else if (isVerb(V.WAVE) && (g.PRSI == GRUE)) {
    tell("There is no grue in sight, but a hissing sound issues forth from the darkness.\n");
    return true;
  } else if (isVerb(V.WAVE, V.RUB, V.RAISE)) {
    if ((g.PRSO == WAND) && !(loc(WAND) == g.WINNER)) {
      tell("You don't have the wand!\n");
      return true;
    } else if (g.WAND_ON || g.SPELL_USED || g.SPELL_VICTIM) {
      if (5 > random(100)) {
        (await JIGS_UP("The wand was still recharging from its last use. It discharges magic all over everything. You turn into a toad, the room fills with a fetid smell, and all sorts of other grubby things happen. Then the wand explodes!"));
      } else {
        tell("A lot you know about magic! A magic wand takes a while to recharge after use! You might cause it to short-circuit!\n");
      }
      return true;
    } else if (isVerb(V.WAVE)) {
      if ((g.PRSO == WAND) && g.PRSI) {
        g.WAND_ON = g.PRSI;
        g.WAND_ON_LOC = g.HERE;
      } else {
        tell("At what?\n");
        return true;
      }
    } else if (isVerb(V.RUB)) {
      if ((g.PRSI == WAND) && g.PRSO) {
        g.WAND_ON = g.PRSO;
      } else {
        tell("Touch what?\n");
        return true;
      }
    } else if (isVerb(V.RAISE)) {
      tell("The wand grows warm and seems to vibrate.\n");
      return true;
    }
    if (g.WAND_ON) {
      g.SPELL_USED = false;
      g.SPELL_VICTIM = false;
      if (g.WAND_ON == ME || g.WAND_ON == WAND) {
        g.WAND_ON = false;
        tell("Fortunately a safety interlock prevents the fatal feedback loop that this would cause.\n");
      } else {
        tell("The wand grows warm, the ", D(g.WAND_ON), " seems to glow dimly with magical essences, and you feel suffused with power.\n");
      }
      enable(await QUEUE(I_WAND.id, 2));
    }
    return true;
  } else {
    return false;
  }
}

async function I_WAND() {
  if (g.WAND_ON && ((g.WAND_ON_LOC == g.HERE) || (loc(g.WAND_ON) == g.WINNER))) {
    tell("The ", D(g.WAND_ON), " stops glowing and the power within you weakens.\n");
    g.WAND_ON = false;
    return true;
  } else {
    g.WAND_ON = false;
    return false;
  }
}

async function WIZARD_QUARTERS_FCN(rarg) {
  let pick = 0, l = 0;
  if (rarg == M_LOOK || rarg == M_FLASH) {
    tell("This is where the Wizard of Frobozz lives. The room is ");
    l = get(g.WIZQDESCS, 0);
    pick = random(l);
    if (pick == g.WIZQLAST) {
      if (pick == l) {
        pick = pick - 1;
      } else {
        pick = pick + 1;
      }
    }
    g.WIZQLAST = pick;
    tell(S(get(g.WIZQDESCS, pick)), "\n");
    return true;
  } else {
    return false;
  }
}

async function BRIDGE_FCN() {
  if (isVerb(V.CROSS)) {
    return await DO_WALK(P.CROSS);
  } else if (isVerb(V.LEAP)) {
    return (await JIGS_UP("You execute a perfect swan-dive into the depths below."));
  } else {
    return false;
  }
}

async function STREAM_FCN() {
  if (isVerb(V.SWIM, V.THROUGH)) {
    tell("You can't swim in the stream.\n");
    return true;
  } else if (isVerb(V.CROSS)) {
    tell("You'll have to find a ford or a bridge.\n");
    return true;
  } else {
    return false;
  }
}

async function CHASM_FCN() {
  if (isVerb(V.LEAP) || (isVerb(V.PUT) && (g.PRSO == ME))) {
    tell("For a change, you look before leaping. You realize you would never survive.\n");
    return true;
  } else if (isVerb(V.CROSS)) {
    tell("You'll have to find a bridge.\n");
    return true;
  } else if (isVerb(V.PUT) && (g.PRSI == PSEUDO_OBJECT)) {
    tell("The ", D(g.PRSO), " drops out of sight into the chasm.\n");
    return remove(g.PRSO);
  } else {
    return false;
  }
}

async function TUNNEL_OBJECT() {
  if (isVerb(V.THROUGH) && getPropAddr(g.HERE, P.IN)) {
    await DO_WALK(P.IN);
    return true;
  } else {
    return await PATH_OBJECT();
  }
}

async function STALA_PSEUDO() {
  if (isVerb(V.TAKE, V.MUNG)) {
    tell("The only ones you can reach are too large to successfully break off.\n");
    return true;
  } else {
    return false;
  }
}

async function MOSS_FCN() {
  if (isVerb(V.TAKE, V.RUB)) {
    tell("Some of the moss rubs off on you, but it stops glowing very quickly once plucked from its environment.\n");
    return true;
  } else {
    return false;
  }
}

async function ROSE_BUSH_FCN() {
  if (isVerb(V.TAKE)) {
    tell("You prick your finger trying to take a rose, and jump back annoyed. The rose almost seemed to move its thorns into your path.\n");
    return true;
  } else {
    return false;
  }
}

async function I_SPELL() {
  if (!g.SPELL_HANDLED$ && g.SPELL_VICTIM) {
    await PERFORM(V.DISENCHANT, g.SPELL_VICTIM);
  }
  g.SPELL_HANDLED$ = false;
  g.WAND_ON = false;
  g.SPELL_USED = false;
  return g.SPELL_VICTIM = false;
}

async function V_DIAGNOSE() {
  if (g.DEAD) {
    tell("You are dead.");
  } else if (g.SPELL$ == S_FERMENT) {
    tell("You are drunk.");
  } else if (g.SPELL$ == S_FEEBLE) {
    tell("You seem unusually weak right now.");
  } else if (g.SPELL$ == S_FLOAT) {
    tell("You seem somewhat light.");
  } else if (g.SPELL$ == S_FREEZE) {
    tell("You are frozen stiff.");
  } else {
    tell("You are in perfect health.");
  }
  crlf();
  if (!(g.DEATHS == 0)) {
    tell("You have been killed ");
    if (g.DEATHS == 1) {
      tell("once.");
    } else if (g.DEATHS == 2) {
      tell("twice.");
    } else {
      tell("an awful lot.");
    }
    return crlf();
  } else {
    return false;
  }
}

async function V_SCORE(ask$ = true) {
  tell("Your score ");
  if (ask$) {
    tell("would be ");
  } else {
    tell("is ");
  }
  tell(N(g.SCORE));
  tell(" (total of 400 points), in ");
  tell(N(g.MOVES));
  if (g.MOVES == 1) {
    tell(" move.");
  } else {
    tell(" moves.");
  }
  crlf();
  tell("This score gives you the rank of ");
  if (g.SCORE == 400) {
    tell("Master Adventurer");
    if (!g.WON_FLAG) {
      tell(", but somehow you don't feel done");
    }
  } else if (g.SCORE > 360) {
    tell("Wizard");
  } else if (g.SCORE > 320) {
    tell("Master");
  } else if (g.SCORE > 240) {
    tell("Adventurer");
  } else if (g.SCORE > 160) {
    tell("Junior Adventurer");
  } else if (g.SCORE > 80) {
    tell("Novice Adventurer");
  } else if (g.SCORE > 40) {
    tell("Amateur Adventurer");
  } else {
    tell("Beginner");
  }
  tell(".\n");
  return g.SCORE;
}

async function JIGS_UP(desc = false, player$ = false) {
  if (desc) {
    tell(S(desc), "\n");
  }
  if (!(ADVENTURER == g.WINNER)) {
    tell(" \n    ****  The ", D(g.WINNER), " has died  **** \n\n");
    remove(g.WINNER);
    g.WINNER = ADVENTURER;
    g.HERE = loc(g.WINNER);
    return M_FATAL;
  }
  for (;;) {
    await SCORE_UPD(-10);
    tell(" \n    ****  You have died  **** \n\n");
    g.DEAD = true;
    g.SPELL$ = false;
    putProp(ADVENTURER, P.ACTION, 0);
    g.DEATHS = g.DEATHS + 1;
    move(g.WINNER, g.HERE);
    tell("Now, let's take a look here... Well, you probably deserve another chance. I can't quite fix you up completely, but you can't have everything.\n\n");
    clearFlag(DEAD_PALANTIR_1, TOUCHBIT);
    clearFlag(DEAD_PALANTIR_2, TOUCHBIT);
    clearFlag(DEAD_PALANTIR_3, TOUCHBIT);
    await RANDOMIZE_OBJECTS();
    await GOTO(DEAD_PALANTIR_1);
    g.P_CONT = false;
    await KILL_INTERRUPTS();
    return M_FATAL;
  }
}

async function RANDOMIZE_OBJECTS() {
  let r = false, f = 0, n_ = 0, l = 0;
  if (loc(LAMP) == g.WINNER) {
    move(LAMP, INSIDE_BARROW);
  }
  n_ = first(g.WINNER);
  for (;;) {
    f = n_;
    if (!f) {
      return true;
    }
    n_ = next(f);
    if ((f == BILLS || f == PORTRAIT) && ((g.HERE == VAULT || g.HERE == DEPOSITORY || g.HERE == OFFICE) || (g.HERE == SMALL_ROOM))) {
      move(f, g.HERE);
    } else if ((f == GOLD_KEY) || (f == CANDY) || (f == PALANTIR_1) || (f == PALANTIR_2) || (f == PALANTIR_3)) {
      move(f, CAROUSEL_ROOM);
    } else if (hasFlag(f, STAGGERED)) {
      move(f, WIZARD_CASE);
    } else {
      move(f, GAZEBO_ROOM);
    }
  }
}

async function KILL_INTERRUPTS() {
  disable(await INT(I_GNOME.id));
  disable(await INT(I_LEDGE.id));
  disable(await INT(I_NERVOUS.id));
  disable(await INT(I_ZGNOME_OUT.id));
  disable(await INT(I_ZGNOME.id));
  await DRAGON_LEAVES();
  disable(await INT(I_MATCH.id));
  return true;
}

async function FIND_WEAPON(o) {
  let w_ = 0;
  w_ = first(o);
  if (!w_) {
    return false;
  }
  for (;;) {
    if (w_ == SWORD) {
      return w_;
    } else if (!(w_ = next(w_))) {
      return false;
    }
  }
}

async function BUCKET_CONT() {
  if (isVerb(V.TAKE) && !(loc(g.WINNER) == BUCKET)) {
    tell("You'll need to get in the bucket to reach it.\n");
    return true;
  } else {
    return false;
  }
}

